     # ==================== Helper Functions ====================
    def normalize_date_for_search(text):
        """
        Normalize different date formats to a common format for comparison
        Handles formats like: 2025-05-15, 15-05-2025, 15/05/2025, 15.05.2025
        And different orders: yyyy-mm-dd, dd-mm-yyyy, mm-dd-yyyy, etc.
        Also handles compact formats like: 210817, 170821, 20210817

        Returns:
            list: All possible normalized date representations
        """
        import re

        if not text or not isinstance(text, str):
            return []

        # Remove extra whitespace
        text = text.strip()

        # Extract potential date patterns
        date_patterns = []

        # Pattern 1: Dates WITH separators (4 digits or 1-2 digits)
        date_regex = r'(\d{1,4})[\/\-\.\s](\d{1,2})[\/\-\.\s](\d{1,4})'
        matches = re.finditer(date_regex, text)

        for match in matches:
            part1, part2, part3 = match.groups()

            # Convert to integers for processing
            try:
                p1, p2, p3 = int(part1), int(part2), int(part3)
            except ValueError:
                continue

            # Determine which part is year, month, day
            normalized_dates = []

            # Case 1: First part is year (yyyy-mm-dd format)
            if p1 >= 1900 and p1 <= 2100:
                if 1 <= p2 <= 12 and 1 <= p3 <= 31:
                    # Separated formats
                    normalized_dates.append(f"{p1:04d}-{p2:02d}-{p3:02d}")
                    normalized_dates.append(f"{p3:02d}-{p2:02d}-{p1:04d}")
                    normalized_dates.append(f"{p3:02d}/{p2:02d}/{p1:04d}")
                    normalized_dates.append(f"{p3:02d}.{p2:02d}.{p1:04d}")
                    # Compact formats
                    normalized_dates.append(f"{p1:04d}{p2:02d}{p3:02d}")  # YYYYMMDD: 20210429
                    normalized_dates.append(f"{str(p1)[2:]}{p2:02d}{p3:02d}")  # YYMMDD: 210429
                    normalized_dates.append(f"{p3:02d}{p2:02d}{str(p1)[2:]}")  # DDMMYY: 290421
                    normalized_dates.append(f"{p3:02d}{p2:02d}{p1:04d}")  # DDMMYYYY: 29042021

            # Case 2: Last part is year (dd-mm-yyyy or mm-dd-yyyy format)
            if p3 >= 1900 and p3 <= 2100:
                # dd-mm-yyyy
                if 1 <= p1 <= 31 and 1 <= p2 <= 12:
                    # Separated formats
                    normalized_dates.append(f"{p3:04d}-{p2:02d}-{p1:02d}")
                    normalized_dates.append(f"{p1:02d}-{p2:02d}-{p3:04d}")
                    normalized_dates.append(f"{p1:02d}/{p2:02d}/{p3:04d}")
                    normalized_dates.append(f"{p1:02d}.{p2:02d}.{p3:04d}")
                    # Compact formats
                    normalized_dates.append(f"{p3:04d}{p2:02d}{p1:02d}")  # YYYYMMDD: 20210429
                    normalized_dates.append(f"{str(p3)[2:]}{p2:02d}{p1:02d}")  # YYMMDD: 210429
                    normalized_dates.append(f"{p1:02d}{p2:02d}{str(p3)[2:]}")  # DDMMYY: 290421
                    normalized_dates.append(f"{p1:02d}{p2:02d}{p3:04d}")  # DDMMYYYY: 29042021

                # mm-dd-yyyy
                if 1 <= p1 <= 12 and 1 <= p2 <= 31:
                    # Separated formats
                    normalized_dates.append(f"{p3:04d}-{p1:02d}-{p2:02d}")
                    normalized_dates.append(f"{p2:02d}-{p1:02d}-{p3:04d}")
                    normalized_dates.append(f"{p2:02d}/{p1:02d}/{p3:04d}")
                    normalized_dates.append(f"{p2:02d}.{p1:02d}.{p3:04d}")
                    # Compact formats
                    normalized_dates.append(f"{p3:04d}{p1:02d}{p2:02d}")  # YYYYMMDD: 20210429
                    normalized_dates.append(f"{str(p3)[2:]}{p1:02d}{p2:02d}")  # YYMMDD: 210429
                    normalized_dates.append(f"{p2:02d}{p1:02d}{str(p3)[2:]}")  # DDMMYY: 290421
                    normalized_dates.append(f"{p2:02d}{p1:02d}{p3:04d}")  # DDMMYYYY: 29042021

            # Case 3: Year in middle (rare but possible)
            if p2 >= 1900 and p2 <= 2100:
                if 1 <= p1 <= 31 and 1 <= p3 <= 12:
                    # Separated formats
                    normalized_dates.append(f"{p2:04d}-{p3:02d}-{p1:02d}")
                    normalized_dates.append(f"{p1:02d}-{p3:02d}-{p2:04d}")
                    normalized_dates.append(f"{p1:02d}/{p3:02d}/{p2:04d}")
                    normalized_dates.append(f"{p1:02d}.{p3:02d}.{p2:04d}")
                    # Compact formats
                    normalized_dates.append(f"{p2:04d}{p3:02d}{p1:02d}")  # YYYYMMDD: 20210429
                    normalized_dates.append(f"{str(p2)[2:]}{p3:02d}{p1:02d}")  # YYMMDD: 210429
                    normalized_dates.append(f"{p1:02d}{p3:02d}{str(p2)[2:]}")  # DDMMYY: 290421
                    normalized_dates.append(f"{p1:02d}{p3:02d}{p2:04d}")  # DDMMYYYY: 29042021

            date_patterns.extend(normalized_dates)

        # Pattern 2: Compact dates WITHOUT separators (6 or 8 digits)
        # Matches: YYMMDD (210429), DDMMYY (290421), YYYYMMDD (20210429), DDMMYYYY (29042021)
        # Also matches dates embedded in text like "210429xyz" or "abc210429def"
        compact_regex = r'(\d{6}|\d{8})'
        compact_matches = re.finditer(compact_regex, text)

        for match in compact_matches:
            compact_date = match.group(1)

            if len(compact_date) == 6:
                # 6-digit format: YYMMDD or DDMMYY
                try:
                    # Try YYMMDD format
                    yy = int(compact_date[0:2])
                    mm = int(compact_date[2:4])
                    dd = int(compact_date[4:6])

                    if 1 <= mm <= 12 and 1 <= dd <= 31:
                        # Assume 20xx for years
                        yyyy = 2000 + yy
                        # Add all format variations
                        date_patterns.append(f"{yyyy:04d}-{mm:02d}-{dd:02d}")  # YYYY-MM-DD
                        date_patterns.append(f"{dd:02d}-{mm:02d}-{yyyy:04d}")  # DD-MM-YYYY
                        date_patterns.append(f"{yyyy:04d}{mm:02d}{dd:02d}")    # YYYYMMDD
                        date_patterns.append(f"{yy:02d}{mm:02d}{dd:02d}")      # YYMMDD (original)
                        date_patterns.append(f"{dd:02d}{mm:02d}{yy:02d}")      # DDMMYY

                    # Try DDMMYY format
                    dd2 = int(compact_date[0:2])
                    mm2 = int(compact_date[2:4])
                    yy2 = int(compact_date[4:6])

                    if 1 <= mm2 <= 12 and 1 <= dd2 <= 31:
                        yyyy2 = 2000 + yy2
                        date_patterns.append(f"{yyyy2:04d}-{mm2:02d}-{dd2:02d}")  # YYYY-MM-DD
                        date_patterns.append(f"{dd2:02d}-{mm2:02d}-{yyyy2:04d}")  # DD-MM-YYYY
                        date_patterns.append(f"{yyyy2:04d}{mm2:02d}{dd2:02d}")    # YYYYMMDD
                        date_patterns.append(f"{yy2:02d}{mm2:02d}{dd2:02d}")      # YYMMDD
                        date_patterns.append(f"{dd2:02d}{mm2:02d}{yy2:02d}")      # DDMMYY (original)
                except (ValueError, IndexError):
                    pass

            elif len(compact_date) == 8:
                # 8-digit format: YYYYMMDD or DDMMYYYY
                try:
                    # Try YYYYMMDD format
                    yyyy = int(compact_date[0:4])
                    mm = int(compact_date[4:6])
                    dd = int(compact_date[6:8])

                    if 1900 <= yyyy <= 2100 and 1 <= mm <= 12 and 1 <= dd <= 31:
                        yy = int(str(yyyy)[2:])
                        date_patterns.append(f"{yyyy:04d}-{mm:02d}-{dd:02d}")  # YYYY-MM-DD
                        date_patterns.append(f"{dd:02d}-{mm:02d}-{yyyy:04d}")  # DD-MM-YYYY
                        date_patterns.append(f"{yyyy:04d}{mm:02d}{dd:02d}")    # YYYYMMDD (original)
                        date_patterns.append(f"{yy:02d}{mm:02d}{dd:02d}")      # YYMMDD
                        date_patterns.append(f"{dd:02d}{mm:02d}{yy:02d}")      # DDMMYY

                    # Try DDMMYYYY format
                    dd2 = int(compact_date[0:2])
                    mm2 = int(compact_date[2:4])
                    yyyy2 = int(compact_date[4:8])

                    if 1 <= mm2 <= 12 and 1 <= dd2 <= 31 and 1900 <= yyyy2 <= 2100:
                        yy2 = int(str(yyyy2)[2:])
                        date_patterns.append(f"{yyyy2:04d}-{mm2:02d}-{dd2:02d}")  # YYYY-MM-DD
                        date_patterns.append(f"{dd2:02d}-{mm2:02d}-{yyyy2:04d}")  # DD-MM-YYYY
                        date_patterns.append(f"{yyyy2:04d}{mm2:02d}{dd2:02d}")    # YYYYMMDD
                        date_patterns.append(f"{yy2:02d}{mm2:02d}{dd2:02d}")      # YYMMDD
                        date_patterns.append(f"{dd2:02d}{mm2:02d}{yy2:02d}")      # DDMMYY
                        date_patterns.append(f"{dd2:02d}{mm2:02d}{yyyy2:04d}")    # DDMMYYYY (original)
                except (ValueError, IndexError):
                    pass

        # Remove duplicates and return
        return list(set(date_patterns))

    def normalize_amount_for_search(text):
        """
        Normalize different amount formats to extract the numeric value.
        Handles formats like: $6789.00, $6,789, 6789.00$, #6789.00#, %6,789%, etc.

        Args:
            text (str): Text that may contain an amount

        Returns:
            list: All possible numeric representations of the amount
        """
        import re

        if not text or not isinstance(text, str):
            return []

        amount_patterns = []

        # Remove common currency symbols and separators, keep only digits and decimal point
        # Pattern: Extract numbers with optional thousand separators and decimal points
        # Matches: $6,789.00, 6789.00$, #6,789#, %6789%, (6789.00), etc.
        amount_regex = r'[\$#%€£¥₹₽¢]?\s*(\d{1,3}(?:[,\s]\d{3})*(?:\.\d{1,4})?|\d+(?:\.\d{1,4})?)\s*[\$#%€£¥₹₽¢]?'

        matches = re.finditer(amount_regex, text)

        for match in matches:
            amount_str = match.group(1)

            if not amount_str:
                continue

            # Remove thousand separators (commas and spaces)
            clean_amount = amount_str.replace(',', '').replace(' ', '')

            try:
                # Convert to float to validate it's a number
                amount_value = float(clean_amount)

                # Generate multiple format variations
                # 1. Original cleaned format
                amount_patterns.append(clean_amount)

                # 2. Without decimal point (if it has decimals)
                if '.' in clean_amount:
                    without_decimal = clean_amount.replace('.', '')
                    amount_patterns.append(without_decimal)

                    # 3. Integer part only
                    integer_part = clean_amount.split('.')[0]
                    amount_patterns.append(integer_part)

                    # 4. With different decimal places
                    decimal_part = clean_amount.split('.')[1]
                    # If decimal is .00, also try without it
                    if decimal_part == '00' or decimal_part == '0':
                        amount_patterns.append(integer_part)

                # 5. With thousand separators (comma)
                if amount_value >= 1000:
                    formatted_with_comma = f"{amount_value:,.2f}".rstrip('0').rstrip('.')
                    amount_patterns.append(formatted_with_comma)
                    # Also without decimals
                    formatted_int = f"{int(amount_value):,}"
                    amount_patterns.append(formatted_int)

                # 6. Just the numeric string representation
                amount_patterns.append(str(amount_value))
                amount_patterns.append(str(int(amount_value)))

            except (ValueError, IndexError):
                continue

        # Remove duplicates and return
        return list(set(amount_patterns))

    def is_amount_field(text):
        """
        Check if the search text looks like an amount/number.

        Args:
            text (str): The search text

        Returns:
            bool: True if it looks like an amount
        """
        import re

        # Check if text is primarily numeric (with optional decimal point and thousand separators)
        # Examples: "6789.00", "6,789", "6789", "123.45"
        amount_pattern = r'^\d{1,3}(?:[,\s]\d{3})*(?:\.\d{1,4})?$|^\d+(?:\.\d{1,4})?$'
        return bool(re.match(amount_pattern, text.strip()))

    def is_date_in_valid_context(text, date_pattern):
        """
        Check if a date pattern appears in a valid context (not part of SWIFT codes,
        reference numbers, or other structured identifiers).

        Args:
            text (str): The OCR text containing the date
            date_pattern (str): The date pattern to check

        Returns:
            bool: True if date is in valid context, False otherwise
        """
        import re

        # If the date is the entire text or very close to it, it's valid
        text_clean = re.sub(r'[^a-zA-Z0-9]', '', text.lower())
        date_clean = re.sub(r'[^a-zA-Z0-9]', '', date_pattern.lower())

        # If date is 80%+ of the text content, it's standalone (GOOD)
        if len(date_clean) >= len(text_clean) * 0.8:
            return True

        # Find the position of the date in the text
        pos = text.lower().find(date_pattern.lower())
        if pos == -1:
            return False

        # Check characters around the date
        before_date = text[:pos] if pos > 0 else ""
        after_date = text[pos + len(date_pattern):] if pos + len(date_pattern) < len(text) else ""

        # PRIMARY BAD CONTEXT CHECK: SWIFT-specific patterns (very strict)
        swift_patterns = [
            r'[A-Z]{3}[A-Z]{2}[A-Z]{2}XXX',  # SWIFT BIC: ABDIAEADAXXX (country+location+XXX)
            r'XXX[0-9]{10,}',  # XXX followed by long number
            r'F21[A-Z]{6}[A-Z]{2}XXX',  # F21 + SWIFT BIC format
        ]

        for pattern in swift_patterns:
            if re.search(pattern, text, re.IGNORECASE):
                return False

        # SECONDARY BAD CONTEXT: Structured SWIFT message format
        if re.search(r'\{[0-9]+:\s*[0-9]+\}', text):  # {177:2104291726} format
            return False

        # Check what comes immediately after the date
        if after_date and len(after_date.strip()) > 0:
            after_stripped = after_date.strip()

            # BAD: Date followed immediately (no space) by random alphanumeric code (SWIFT style)
            # Pattern: 210817ABCDXYZQWER (mixed case nonsense)
            if pos + len(date_pattern) < len(text) and text[pos + len(date_pattern)] != ' ':
                # No space after date - check if it's a code or a real word
                # Extract the immediate next segment
                next_segment_match = re.match(r'^([A-Z0-9]+)', after_date, re.IGNORECASE)
                if next_segment_match:
                    next_segment = next_segment_match.group(1)

                    # If it's all uppercase AND contains XXX pattern, it's SWIFT
                    if next_segment.isupper() and 'XXX' in next_segment:
                        return False

                    # If it's a mix of uppercase and weird patterns (non-word), reject
                    # Example: ABDIAEADAXXX - not a real word
                    # But allow: BENEFICIARY, COUNTRY - real words
                    if len(next_segment) >= 10:
                        # Long segment - check if it's gibberish or real words
                        # Real words are more likely to have vowel patterns
                        vowels = sum(1 for c in next_segment.lower() if c in 'aeiou')
                        consonants = sum(1 for c in next_segment.lower() if c.isalpha() and c not in 'aeiou')

                        # If very few vowels relative to length, it's likely a code
                        if len(next_segment) > 10 and vowels < len(next_segment) * 0.2:
                            return False

        # GOOD CONTEXT PATTERNS (these indicate a standalone date or labeled date)
        good_patterns = [
            # Date labels
            r'date[:\s]*$',
            r'dated[:\s]*$',
            r'on[:\s]*$',
            r'from[:\s]*$',
            r'to[:\s]*$',
            r'due[:\s]*$',
            r'value[:\s]*$',
            r'issued[:\s]*$',
            r'expire[:\s]*$',
            r'valid[:\s]*$',
        ]

        # Check if before_date contains good indicators
        before_lower = before_date.lower().strip()
        for pattern in good_patterns:
            if re.search(pattern, before_lower):
                return True

        # Check if after_date starts with a space (indicates separate field)
        if after_date and after_date[0] in [' ', '\t', '\n', ':', '-', '/']:
            return True

        # Check if text has common field separators around the date
        if ':' in before_date or ':' in after_date[:5] if len(after_date) >= 5 else False:
            return True

        # If text is relatively short and no SWIFT patterns, accept it
        # This handles cases like "210817BENEFICIARY" where BENEFICIARY is a real word
        if len(text) < 50 and not re.search(r'XXX[0-9]{5,}', text):
            return True

        # Default: if no strong bad patterns detected, consider it valid
        return True

    def calculate_match_priority_score(match_text, field_value, match_confidence, match_type):
        """
        Calculate a priority score for a match to rank field values higher than narrative text.

        Args:
            match_text (str): The matched OCR text
            field_value (str): The search query
            match_confidence (float): The match confidence percentage
            match_type (str): Type of match (exact, contains, etc.)

        Returns:
            float: Priority score (higher = better priority)
        """
        import re

        priority_score = match_confidence  # Start with base confidence

        # Factor 1: Text length - shorter is better (likely a field value)
        text_len = len(match_text)
        if text_len <= 20:
            priority_score += 15  # Very short - likely a label/field
        elif text_len <= 40:
            priority_score += 10  # Short - possibly a field
        elif text_len <= 60:
            priority_score += 5   # Medium - could be either
        else:
            priority_score -= 10  # Long - likely narrative text

        # Factor 2: Field value is near the start of the text
        field_pos = match_text.lower().find(field_value.lower())
        if field_pos == 0:
            priority_score += 10  # Starts with field value - excellent
        elif field_pos <= 3:
            priority_score += 5   # Near the start - good

        # Factor 3: Format patterns indicating field definitions
        # Example: "USD (US DOLLAR)" - field with description in parentheses
        if re.search(rf'\b{re.escape(field_value)}\s*\([^)]+\)', match_text, re.IGNORECASE):
            priority_score += 20  # Field with description pattern

        # Factor 4: Detect sentence patterns (narrative text indicators)
        sentence_indicators = [
            r'\b(we|will|shall|must|should|may|can)\b',  # Modal verbs
            r'\b(the|a|an)\b.*\b(the|a|an)\b',  # Multiple articles
            r'\b(of|with|for|from|by)\b',  # Prepositions in narrative
            r'[.!?]\s',  # Sentence endings
            r'^\d+\.',  # Numbered list items (e.g., "6. WE WILL...")
        ]

        for pattern in sentence_indicators:
            if re.search(pattern, match_text, re.IGNORECASE):
                priority_score -= 15  # Penalize narrative text
                break

        # Factor 5: Detect amount mentions (e.g., "USD 100/-", "USD100", "100USD")
        # These are less relevant than currency field definitions
        # Match patterns: USD100, USD 100, 100USD, etc.
        amount_patterns = [
            rf'\b{re.escape(field_value)}\s*\d+',  # USD100 or USD 100
            rf'\d+\s*{re.escape(field_value)}\b',  # 100USD or 100 USD
        ]
        for pattern in amount_patterns:
            if re.search(pattern, match_text, re.IGNORECASE):
                priority_score -= 10  # Currency amount mention, not field definition
                break

        # Factor 6: Check if match is mostly the field value (high ratio)
        field_ratio = len(field_value) / len(match_text) if len(match_text) > 0 else 0
        if field_ratio > 0.5:
            priority_score += 15  # Field value is >50% of text - very relevant
        elif field_ratio > 0.3:
            priority_score += 8   # Field value is >30% of text - relevant

        # Factor 7: Exact match type bonus
        if match_type == 'exact':
            priority_score += 5
        elif match_type in ['date_exact', 'date_contains', 'amount_exact', 'amount_contains']:
            priority_score += 3

        return priority_score

    def search_text_in_ocr(field_value, ocr_data, search_mode='exact'):
        """
        Search for text in OCR data and return matching entries with coordinates

        Args:
            field_value (str): The text to search for
            ocr_data (list): List of OCR entries with text and bounding box data
            search_mode (str): Search strategy - 'exact', 'fuzzy', or 'contains'

        Returns:
            list: Matching OCR entries with coordinates and confidence scores
        """
        import time
        from difflib import SequenceMatcher

        logger.info("SEARCH: === STARTING OCR TEXT SEARCH ===")
        logger.info(f"TARGET: Target field value: '{field_value}'")
        logger.info(f" Search mode: {search_mode}")
        logger.info(f" OCR entries to search: {len(ocr_data)}")

        if not field_value or not field_value.strip():
            logger.warning("ERROR: Empty field value provided")
            return []

        if not ocr_data:
            logger.warning("ERROR: No OCR data provided")
            return []

        field_value_lower = field_value.lower().strip()
        matches = []

        # Check if field_value looks like a date and normalize it
        field_date_patterns = normalize_date_for_search(field_value)
        is_date_search = len(field_date_patterns) > 0
        
        # Check if field_value is a LONG numeric identifier (e.g., LC number, transaction ID, reference number)
        # These should be treated as exact text search, NOT amount search
        # PRIORITY: Check this BEFORE amount detection to avoid false matches
        is_numeric_identifier = False
        if not is_date_search:
            numeric_value = field_value.strip()
            # Long numeric strings (>10 digits, no decimals/separators) are identifiers, not amounts
            # Examples: "1619699496468609" (16 digits), "0153944873" (10+ digits)
            if numeric_value.isdigit() and len(numeric_value) > 10:
                is_numeric_identifier = True
                logger.info(f"🔢 Detected numeric identifier search: '{numeric_value}' ({len(numeric_value)} digits - will match exact text only, not as amount)")
        
        # Check if field_value is a simple number (e.g., "21" for "Period of presentation")
        # This handles cases where user searches "21" but OCR has "21 Days", "21 DAYS", "21/Days", etc.
        # PRIORITY: Check this BEFORE amount detection since simple numbers like "21" should be treated as periods
        is_numeric_period = False
        if not is_date_search and not is_numeric_identifier:
            # Check if it's just a simple integer (1-3 digits, no decimals or currency)
            numeric_value = field_value.strip()
            if numeric_value.isdigit() and len(numeric_value) <= 3:  # Period values are typically small numbers
                is_numeric_period = True
                logger.info(f"📅 Detected numeric period search: '{numeric_value}' (will match variations like '{numeric_value} Days', '{numeric_value}/DAYS', etc.)")

        # Check if field_value looks like an amount and normalize it
        # Only check for amount if it's not a date, numeric identifier, or numeric period
        field_amount_patterns = []
        is_amount_search = False
        if not is_date_search and not is_numeric_identifier and not is_numeric_period:
            is_amount_search = is_amount_field(field_value)
            if is_amount_search:
                field_amount_patterns = normalize_amount_for_search(field_value)

        if is_date_search:
            logger.info(f"Detected date search. Normalized patterns: {field_date_patterns}")
        elif is_numeric_identifier:
            logger.info(f"🔢 Searching for numeric identifier: '{field_value}' (exact/contains match only)")
        elif is_numeric_period:
            logger.info(f"📅 Searching for numeric period: '{field_value}' with day/time variations")
        elif is_amount_search:
            logger.info(f"💰 Detected amount search. Normalized patterns: {field_amount_patterns}")
        else:
            logger.info(f"INFO: Searching for phrase/sentence: '{field_value}'")

        # Search statistics
        exact_matches = 0
        fuzzy_matches = 0
        contains_matches = 0
        partial_matches = 0
        date_matches = 0
        amount_matches = 0
        numeric_period_matches = 0
        no_matches = 0

        logger.info(f"Starting sentence/phrase search through {len(ocr_data)} OCR entries")

        for i, ocr_entry in enumerate(ocr_data):
            ocr_text = ocr_entry.get('text', '').strip()

            if not ocr_text:
                logger.debug(f"   Entry {i+1}: Skipping empty text")
                continue

            ocr_text_lower = ocr_text.lower()
            match_confidence = 0
            match_type = 'none'

            logger.debug(f"   Entry {i+1}: Comparing '{field_value_lower}' with '{ocr_text_lower}'")

            # Date matching logic (highest priority for date searches)
            if is_date_search and match_confidence < 100:
                ocr_date_patterns = normalize_date_for_search(ocr_text)
                if ocr_date_patterns:
                    # Check if any normalized date patterns match (exact or contained)
                    for field_pattern in field_date_patterns:
                        for ocr_pattern in ocr_date_patterns:
                            if field_pattern == ocr_pattern:
                                # Validate that this is a genuine standalone date, not part of SWIFT code
                                if is_date_in_valid_context(ocr_text, ocr_pattern):
                                    match_confidence = 100
                                    match_type = 'date_exact'
                                    date_matches += 1
                                    match_info = f"'{field_pattern}' matches '{ocr_pattern}'"
                                    logger.debug(f"      SUCCESS: DATE EXACT MATCH! {match_info} - Confidence: 100%")
                                    break
                                else:
                                    logger.debug(f"      REJECTED: Date '{ocr_pattern}' in invalid context (likely SWIFT/reference code)")
                        if match_confidence == 100:
                            break

                # If no exact date match, check if date pattern is contained in OCR text
                # This handles cases like "210429xyz" where the date is embedded in text
                # BUT we validate it's not part of SWIFT codes or reference numbers
                if match_confidence < 100:
                    for field_pattern in field_date_patterns:
                        if field_pattern in ocr_text_lower:
                            # Check if the date is in a valid context (not SWIFT code)
                            if is_date_in_valid_context(ocr_text, field_pattern):
                                match_confidence = 95
                                match_type = 'date_contains'
                                date_matches += 1
                                match_info = f"'{field_pattern}' found in '{ocr_text_lower}'"
                                logger.debug(f"      SUCCESS: DATE CONTAINS MATCH! {match_info} - Confidence: 95%")
                                break
                            else:
                                logger.debug(f"      REJECTED: Date '{field_pattern}' in invalid context (likely SWIFT/reference code)")

            # Amount matching logic (for numeric/currency searches)
            if is_amount_search and match_confidence < 100:
                ocr_amount_patterns = normalize_amount_for_search(ocr_text)
                if ocr_amount_patterns:
                    # Check if any normalized amount patterns match
                    for field_pattern in field_amount_patterns:
                        for ocr_pattern in ocr_amount_patterns:
                            if field_pattern == ocr_pattern:
                                match_confidence = 100
                                match_type = 'amount_exact'
                                amount_matches += 1
                                match_info = f"'{field_pattern}' matches '{ocr_pattern}'"
                                logger.debug(f"      SUCCESS: 💰 AMOUNT EXACT MATCH! {match_info} - Confidence: 100%")
                                break
                        if match_confidence == 100:
                            break

                # If no exact amount match, check if amount pattern is contained in OCR text
                if match_confidence < 100:
                    for field_pattern in field_amount_patterns:
                        if field_pattern in ocr_text:
                            match_confidence = 95
                            match_type = 'amount_contains'
                            amount_matches += 1
                            match_info = f"'{field_pattern}' found in '{ocr_text}'"
                            logger.debug(f"      SUCCESS: 💰 AMOUNT CONTAINS MATCH! {match_info} - Confidence: 95%")
                            break

            # Numeric period matching (e.g., "21" matches "21 Days", "21 DAYS", "21/Days", etc.)
            # STRICT: Only match when followed by "days" - don't match standalone numbers or dates
            if is_numeric_period and match_confidence < 100:
                import re
                # Create pattern to match the number followed by REQUIRED separator and "days" variants
                # Handles: "21 Days", "21 DAYS", "21/Days", "21/DAYS", "21Days", "21-Days", etc.
                # Does NOT match: "21", "29/04/21", "210429", "ILCAE00221000098"
                number = re.escape(field_value.strip())
                # Pattern: the number followed by optional space/slash/hyphen, then REQUIRED "days" (case-insensitive)
                # Using lookahead to ensure "days" exists
                pattern = rf'\b{number}\s*[/\-\s]?\s*(days?|DAYS?)\b'

                match = re.search(pattern, ocr_text, re.IGNORECASE)
                if match:
                    match_confidence = 100
                    match_type = 'numeric_period'
                    numeric_period_matches += 1
                    logger.debug(f"      SUCCESS: 📅 NUMERIC PERIOD MATCH! '{number} Days' pattern found in '{ocr_text}' - Confidence: 100%")
            
            # Regular exact/contains/partial match
            # For numeric identifiers: allow exact/contains (no word boundary, no partial/fuzzy)
            # For numeric periods: skip entirely (use "X Days" pattern only)
            if match_confidence < 100 and search_mode in ['exact', 'fuzzy', 'contains'] and not is_numeric_period:
                if field_value_lower == ocr_text_lower:
                    match_confidence = 100
                    match_type = 'exact'
                    exact_matches += 1
                    logger.debug("      SUCCESS: EXACT MATCH! Confidence: 100%")
                elif field_value_lower in ocr_text_lower:
                    import re  # Import regex module for word boundary checking
                    # For numeric identifiers: simple contains match (no word boundary checking)
                    if is_numeric_identifier:
                        match_confidence = 100
                        match_type = 'contains'
                        contains_matches += 1
                        logger.debug(f"      SUCCESS: 🔢 NUMERIC IDENTIFIER CONTAINS MATCH! '{field_value_lower}' found in '{ocr_text_lower}' - Confidence: 100%")
                    # Use strict word boundary checking for short search terms (≤20 chars)
                    # e.g., "Allowed" should NOT match "Not Allowed" or "Not-Allowed"
                    # "Not-Allowed" should NOT match "Allowed"
                    elif len(field_value_lower) <= 20:
                        # STRICT: Search term must be at START of text or preceded ONLY by punctuation (not words)
                        # This ensures "Allowed" doesn't match "Not Allowed" or "Pre-Allowed"
                        # But "Allowed" matches "Allowed", "(Allowed)", "[Allowed Shipment]"
                        pattern = r'^' + re.escape(field_value_lower) + r'(?:$|[\s\-,./;:()\[\]{}|])'
                        match_start = re.match(pattern, ocr_text_lower)

                        # Also check if preceded by punctuation only (not alphanumeric)
                        pattern_with_punct = r'(?:^|[^\w])' + re.escape(field_value_lower) + r'(?:$|[\s\-,./;:()\[\]{}|])'
                        match_punct = re.search(pattern_with_punct, ocr_text_lower)

                        # Only match if it starts the text or is preceded by non-word characters
                        # This rejects: "Not Allowed" when searching "Allowed" (preceded by word "Not")
                        # This accepts: "Allowed", "(Allowed)", "Allowed Shipment"
                        if match_start or (match_punct and not re.search(r'\w+\s+' + re.escape(field_value_lower), ocr_text_lower)):
                            match_confidence = 90
                            match_type = 'contains'
                            contains_matches += 1
                            contains_info = f"'{field_value_lower}' found as complete word in '{ocr_text_lower}'"
                            logger.debug(f"      SUCCESS: CONTAINS MATCH (strict word boundary)! {contains_info} - Confidence: 90%")
                        else:
                            # Found as substring but preceded by another word - skip it
                            logger.debug(f"      REJECTED: '{field_value_lower}' found in '{ocr_text_lower}' but preceded by another word (e.g., 'Allowed' in 'Not Allowed')")
                    else:
                        # For longer phrases, use regular substring matching
                        match_confidence = 90
                        match_type = 'contains'
                        contains_matches += 1
                        contains_info = f"'{field_value_lower}' found in '{ocr_text_lower}'"
                        logger.debug(f"      SUCCESS: CONTAINS MATCH! {contains_info} - Confidence: 90%")
                elif ocr_text_lower in field_value_lower and not is_numeric_identifier:
                    # Skip partial matches for numeric identifiers (we only want exact/contains)
                    # Apply same strict word boundary checking for short OCR text in partial matches
                    # e.g., when searching "Not Allowed", don't match OCR text "Allowed"
                    import re
                    if len(ocr_text_lower) <= 20:
                        # STRICT: OCR text must be at START of search term or preceded ONLY by punctuation
                        # This ensures searching "Not Allowed" doesn't match "Allowed"
                        pattern = r'^' + re.escape(ocr_text_lower) + r'(?:$|[\s\-,./;:()\[\]{}|])'
                        match_start = re.match(pattern, field_value_lower)

                        # Also check if preceded by punctuation only (not alphanumeric)
                        pattern_with_punct = r'(?:^|[^\w])' + re.escape(ocr_text_lower) + r'(?:$|[\s\-,./;:()\[\]{}|])'
                        match_punct = re.search(pattern_with_punct, field_value_lower)

                        # Only match if it starts the search term or is preceded by non-word characters
                        if match_start or (match_punct and not re.search(r'\w+\s+' + re.escape(ocr_text_lower), field_value_lower)):
                            match_confidence = 85
                            match_type = 'partial'
                            partial_matches += 1
                            partial_info = f"'{ocr_text_lower}' found as complete word in '{field_value_lower}'"
                            logger.debug(f"      SUCCESS: PARTIAL MATCH (strict word boundary)! {partial_info} - Confidence: 85%")
                        else:
                            # Found as substring but preceded by another word - skip it
                            logger.debug(f"      REJECTED: '{ocr_text_lower}' found in '{field_value_lower}' but preceded by another word (e.g., 'Allowed' in 'Not Allowed')")
                    else:
                        # For longer OCR text, use regular substring matching
                        match_confidence = 85
                        match_type = 'partial'
                        partial_matches += 1
                        partial_info = f"'{ocr_text_lower}' found in '{field_value_lower}'"
                        logger.debug(f"      SUCCESS: PARTIAL MATCH! {partial_info} - Confidence: 85%")
            
            # Fuzzy matching if enabled and no exact match (skip for numeric period/identifier searches)
            if search_mode in ['fuzzy', 'contains'] and match_confidence < 90 and not is_numeric_period and not is_numeric_identifier:
                similarity = SequenceMatcher(None, field_value_lower, ocr_text_lower).ratio()
                logger.debug(f"Fuzzy similarity: {similarity:.3f}")
                if similarity >= 0.8:  # High similarity threshold
                    fuzzy_confidence = similarity * 80
                    if fuzzy_confidence > match_confidence:
                        match_confidence = fuzzy_confidence
                        match_type = 'fuzzy'
                        fuzzy_matches += 1
                        logger.debug(f"      SUCCESS:FUZZY MATCH! Similarity: {similarity:.3f} - Confidence: {fuzzy_confidence:.1f}%")

            if match_confidence < 80:
                no_matches += 1
                logger.debug(f"No sufficient match (confidence: {match_confidence:.1f}%)")

            # Only include high-confidence matches
            if match_confidence >= 80:
                # Filter out small partial matches for long search phrases
                # Use dynamic threshold: longer searches require larger matches
                # FOR VERY LONG MULTI-LINE: Use relaxed threshold, rely on post-processing spatial filtering
                if match_type == 'partial':
                    search_length = len(field_value)
                    match_length = len(ocr_text.strip())

                    # Dynamic filtering based on search phrase length:
                    # - Short phrases (30-50 chars): skip matches ≤4 chars
                    # - Medium phrases (50-100 chars): skip matches ≤10 chars
                    # - Long phrases (100-200 chars): skip matches ≤20 chars
                    # - Very long multi-line (200+ chars): skip matches ≤30 chars (balanced to filter isolated phrases while keeping substantial lines)
                    skip_match = False

                    if search_length > 200:
                        # Very long multi-line: Filter isolated short phrases (e.g., company names appearing elsewhere)
                        # Keep substantial content lines (31+ chars) which are more likely to be part of the main block
                        if match_length <= 30:
                            skip_match = True
                            logger.debug(f"Skipping small partial match '{ocr_text[:50]}...' ({match_length} chars ≤30 for {search_length}-char search)")
                    elif search_length > 100:
                        if match_length <= 20:
                            skip_match = True
                            logger.debug(f"Skipping small partial match '{ocr_text}' ({match_length} chars ≤20 for {search_length}-char search)")
                    elif search_length > 50:
                        if match_length <= 10:
                            skip_match = True
                            logger.debug(f"Skipping small partial match '{ocr_text}' ({match_length} chars ≤10 for {search_length}-char search)")
                    elif search_length > 30:
                        if match_length <= 4:
                            skip_match = True
                            logger.debug(f"Skipping tiny partial match '{ocr_text}' ({match_length} chars ≤4 for {search_length}-char search)")

                    if skip_match:
                        no_matches += 1
                        continue

                # Calculate priority score for intelligent ranking
                priority_score = calculate_match_priority_score(
                    ocr_text,
                    field_value,
                    match_confidence,
                    match_type
                )

                match_data = {
                    'ocr_index': i,
                    'matched_text': ocr_text,
                    'field_value': field_value,
                    'match_confidence': round(match_confidence, 1),
                    'match_type': match_type,
                    'priority_score': round(priority_score, 1),
                    'bounding_box': ocr_entry.get('bounding_box', []),
                    'bounding_page': ocr_entry.get('bounding_page', 1),
                    'ocr_confidence': ocr_entry.get('confidence', 0)
                }
                matches.append(match_data)

                logger.info(f"SUCCESS:MATCH #{len(matches)}: '{ocr_text}' -> {match_confidence:.1f}% confidence ({match_type}), Priority: {priority_score:.1f}")
                logger.info(f"   OCR Index: {i}, Page: {match_data['bounding_page']}, BBox: {match_data['bounding_box']}")

        # Sort matches by priority score first, then confidence (highest first)
        matches.sort(key=lambda x: (x['priority_score'], x['match_confidence']), reverse=True)
        
        # For multi-line searches (200+ chars), create encompassing bounding boxes per page
        if len(field_value) >= 200 and len(matches) >= 2:
            logger.info(f"📦 MULTI-LINE: Creating encompassing bounding boxes for {len(matches)} matches")
            
            # Group matches by page
            matches_by_page = {}
            for match in matches:
                page = match['bounding_page']
                if page not in matches_by_page:
                    matches_by_page[page] = []
                matches_by_page[page].append(match)
            
            # Create one encompassing box per page
            encompassing_matches = []
            for page, page_matches in matches_by_page.items():
                if len(page_matches) < 2:
                    # Single match on this page, keep as is
                    encompassing_matches.extend(page_matches)
                    continue
                
                # Calculate the encompassing bounding box
                min_x = float('inf')
                min_y = float('inf')
                max_x = float('-inf')
                max_y = float('-inf')
                
                all_texts = []
                
                for match in page_matches:
                    bbox = match['bounding_box']
                    if not bbox or len(bbox) < 4:
                        continue
                    
                    all_texts.append(match['matched_text'])
                    
                    # Extract all coordinate points
                    if len(bbox) == 8:  # x1,y1,x2,y2,x3,y3,x4,y4
                        xs = [bbox[0], bbox[2], bbox[4], bbox[6]]
                        ys = [bbox[1], bbox[3], bbox[5], bbox[7]]
                    else:  # x1,y1,x2,y2
                        xs = [bbox[0], bbox[2]]
                        ys = [bbox[1], bbox[3]]
                    
                    # Update min/max
                    min_x = min(min_x, min(xs))
                    max_x = max(max_x, max(xs))
                    min_y = min(min_y, min(ys))
                    max_y = max(max_y, max(ys))
                
                # Add small padding (0.1 inches on each side)
                padding = 0.1
                min_x = max(0, min_x - padding)
                min_y = max(0, min_y - padding)
                max_x += padding
                max_y += padding
                
                # Create encompassing bounding box (8 coordinates for rectangle)
                encompassing_bbox = [
                    min_x, min_y,      # Top-left
                    max_x, min_y,      # Top-right
                    max_x, max_y,      # Bottom-right
                    min_x, max_y       # Bottom-left
                ]
                
                # Create single match representing the entire section
                combined_text = f"[MULTI-LINE SECTION: {len(page_matches)} lines]"
                
                encompassing_match = {
                    'ocr_index': page_matches[0]['ocr_index'],  # Use first match's index
                    'matched_text': combined_text,
                    'field_value': field_value,
                    'match_confidence': 95.0,  # High confidence for multi-line blocks
                    'match_type': 'multiline_block',
                    'priority_score': 100.0,  # Highest priority
                    'bounding_box': encompassing_bbox,
                    'bounding_page': page,
                    'ocr_confidence': 100,
                    'component_matches': len(page_matches),  # Track how many matches merged
                    'component_texts': all_texts  # Store original texts for reference
                }
                
                encompassing_matches.append(encompassing_match)
                logger.info(f"   ✅ Page {page}: Created encompassing box covering {len(page_matches)} matches")
                logger.info(f"      BBox: [{min_x:.2f}, {min_y:.2f}, {max_x:.2f}, {max_y:.2f}]")
            
            # Replace matches with encompassing boxes
            matches = encompassing_matches
            logger.info(f"📦 MULTI-LINE: Reduced to {len(matches)} encompassing box(es)")
        
        # Log search summary
        logger.info(f"ANALYTICS: === SEARCH STATISTICS ===")
        logger.info(f"   Date matches: {date_matches}")
        logger.info(f"   Amount matches: {amount_matches}")
        logger.info(f"   Numeric period matches: {numeric_period_matches}")
        logger.info(f"   Exact matches: {exact_matches}")
        logger.info(f"   Contains matches: {contains_matches}")
        logger.info(f"   Partial matches: {partial_matches}")
        logger.info(f"   Fuzzy matches: {fuzzy_matches}")
        logger.info(f"   No matches: {no_matches}")
        logger.info(f"   Total qualifying matches: {len(matches)}")

        if matches:
            best_match = matches[0]
            logger.info(f"TARGET: BEST MATCH: '{best_match['matched_text']}' ({best_match['match_confidence']}% {best_match['match_type']}, Priority: {best_match['priority_score']})")
            logger.info(f"   Location: Page {best_match['bounding_page']}, BBox: {best_match['bounding_box']}")

            # Show ranking if multiple matches
            if len(matches) > 1:
                logger.info(f"ANALYTICS: Match ranking (by priority score):")
                for idx, match in enumerate(matches[:5], 1):  # Show top 5
                    match_text_preview = match['matched_text'][:50] + '...' if len(match['matched_text']) > 50 else match['matched_text']
                    logger.info(f"   #{idx}: '{match_text_preview}' - Confidence: {match['match_confidence']}%, Priority: {match['priority_score']}")
        else:
            logger.warning(f"ERROR: NO QUALIFYING MATCHES FOUND for '{field_value}'")
            logger.info(f"IDEA: Search suggestions:")
            if is_date_search:
                logger.info(f"   - Date formats tried: {field_date_patterns}")
                logger.info(f"   - Try different date separators (-, /, .)")
                logger.info(f"   - Verify the date format in the document")
            logger.info(f"   - Try using 'fuzzy' or 'contains' search mode")
            logger.info(f"   - Check if the field value exactly matches the document text")
            logger.info(f"   - Verify the document has been processed and OCR data is available")

        logger.info(f"SAVE: Search complete: returning {len(matches)} matches")
        return matches

    # ==================== Coordinate Search Routes ====================
    @app.route('/api/test_coordinates', methods=['GET'])
    @timing_aspect
    def test_coordinates():
        """Simple test route to verify route registration works"""
        return jsonify({
            'success': True,
            'message': 'Test route is working!',
            'timestamp': str(time.time())
        })

    # ============================================
    # UTILITIES
    # ============================================

    def fuzzy_match(str1: str, str2: str) -> float:
        """Calculate similarity ratio"""
        return SequenceMatcher(None, str1.lower(), str2.lower()).ratio()


    def strip_punctuation(text: str) -> str:
        """Remove leading/trailing punctuation"""
        import string
        return text.strip(string.punctuation + string.whitespace)


    def merge_bboxes(bboxes: List[List[float]], padding: float = 0.01) -> List[float]:
        """Merge multiple bboxes"""
        if not bboxes:
            return []
        
        all_x, all_y = [], []
        for bbox in bboxes:
            if bbox and len(bbox) >= 8:
                all_x.extend([bbox[0], bbox[2], bbox[4], bbox[6]])
                all_y.extend([bbox[1], bbox[3], bbox[5], bbox[7]])
        
        if not all_x or not all_y:
            return []
        
        xmin, ymin = min(all_x) - padding, min(all_y) - padding
        xmax, ymax = max(all_x) + padding, max(all_y) + padding
        
        return [xmin, ymin, xmax, ymin, xmax, ymax, xmin, ymax]


    def get_bbox_center(bbox: List[float]) -> Tuple[float, float]:
        """Get center point of bbox"""
        if not bbox or len(bbox) < 8:
            return (0, 0)
        x = (bbox[0] + bbox[2] + bbox[4] + bbox[6]) / 4
        y = (bbox[1] + bbox[3] + bbox[5] + bbox[7]) / 4
        return (x, y)


    def calculate_distance(bbox1: List[float], bbox2: List[float]) -> float:
        """Calculate Euclidean distance between two bboxes"""
        x1, y1 = get_bbox_center(bbox1)
        x2, y2 = get_bbox_center(bbox2)
        return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)


    def are_words_on_same_line(words: List[Dict], y_tolerance: float = 0.2) -> bool:
        """Check if words are on same horizontal line (for normal pages)"""
        if not words or len(words) < 2:
            return True
        
        y_positions = []
        for word in words:
            bbox = word.get('bounding_box', [])
            if len(bbox) >= 8:
                y_center = (bbox[1] + bbox[3] + bbox[5] + bbox[7]) / 4
                y_positions.append(y_center)
        
        if not y_positions:
            return True
        
        return (max(y_positions) - min(y_positions)) <= y_tolerance


    def are_words_on_same_line_rotated(words: List[Dict], x_tolerance: float = 0.2) -> bool:
        """Check if words are on same line for ROTATED page (similar X, varying Y)"""
        if not words or len(words) < 2:
            return True
        
        x_positions = []
        for word in words:
            bbox = word.get('bounding_box', [])
            if len(bbox) >= 8:
                x_center = (bbox[0] + bbox[2] + bbox[4] + bbox[6]) / 4
                x_positions.append(x_center)
        
        if not x_positions:
            return True
        
        return (max(x_positions) - min(x_positions)) <= x_tolerance


    def sort_words_left_to_right(words: List[Dict]) -> List[Dict]:
        """Sort words left to right (by X position) - for normal pages"""
        return sorted(words, key=lambda w: (w['bounding_box'][0] + w['bounding_box'][2]) / 2)


    def sort_words_for_rotated_page(words: List[Dict]) -> List[Dict]:
        """Sort words for rotated page (by Y coordinate, descending = right to left)"""
        return sorted(words, 
                    key=lambda w: (w['bounding_box'][1] + w['bounding_box'][5]) / 2,
                    reverse=True)


    def sort_words_reading_order(words: List[Dict]) -> List[Dict]:
        """Sort words in reading order (top to bottom, left to right)"""
        return sorted(words, key=lambda w: (
            (w['bounding_box'][1] + w['bounding_box'][5]) / 2,  # Y
            (w['bounding_box'][0] + w['bounding_box'][2]) / 2   # X
        ))


    # ============================================
    # ROTATED PAGE DETECTION
    # ============================================

    def detect_page_rotation(word_pool: List[Dict]) -> bool:
        """
        Detect if page is rotated 90° counter-clockwise
        Rotated page: Y-range >> X-range for most words (text flows on Y-axis)
        """
        if not word_pool or len(word_pool) < 5:
            return False
        
        rotated_count = 0
        valid_count = 0
        
        for word in word_pool:
            if not word or not isinstance(word, dict):
                continue
                
            bbox = word.get('bounding_box', [])
            if not bbox or len(bbox) < 8:
                continue
            
            try:
                x_coords = [bbox[0], bbox[2], bbox[4], bbox[6]]
                y_coords = [bbox[1], bbox[3], bbox[5], bbox[7]]
                
                x_range = max(x_coords) - min(x_coords)
                y_range = max(y_coords) - min(y_coords)
                
                valid_count += 1
                
                # If Y-range > X-range * 1.5 → word flows on Y-axis (rotated)
                if y_range > x_range * 1.5:
                    rotated_count += 1
            except (TypeError, ValueError, IndexError) as e:
                logger.debug(f"Error processing bbox: {e}")
                continue
        
        if valid_count == 0:
            return False
        
        rotation_ratio = rotated_count / valid_count
        is_rotated = rotation_ratio > 0.7
        
        logger.info(f"Page rotation check: {rotation_ratio*100:.1f}% words rotated → {'ROTATED' if is_rotated else 'NORMAL'}")
        
        return is_rotated


    def is_standalone_punctuation(word_text: str) -> bool:
        """Check if word is just punctuation"""
        import string
        return all(c in string.punctuation + string.whitespace for c in word_text)


    def smart_sort_words(matched_words: List[Dict], line_text: str, is_rotated: bool = False) -> List[Dict]:
        """
        Smart sorting that handles punctuation correctly
        If punctuation is far from main text, it might be misplaced
        """
        if len(matched_words) <= 1:
            return matched_words
        
        # Separate punctuation from regular words
        punctuation_words = []
        regular_words = []
        
        for word in matched_words:
            word_text = word.get('text', '').strip()
            if is_standalone_punctuation(word_text):
                punctuation_words.append(word)
            else:
                regular_words.append(word)
        
        # If no punctuation or all punctuation, sort normally
        if not punctuation_words or not regular_words:
            if is_rotated:
                return sort_words_for_rotated_page(matched_words)
            else:
                return sort_words_left_to_right(matched_words)
        
        # Sort regular words
        if is_rotated:
            sorted_regular = sort_words_for_rotated_page(regular_words)
        else:
            sorted_regular = sort_words_left_to_right(regular_words)
        
        # For each punctuation, find where it should go based on expected text
        result = []
        regular_text = ' '.join([w.get('text', '') for w in sorted_regular])
        
        for punct_word in punctuation_words:
            punct_text = punct_word.get('text', '').strip()
            
            # Find where this punctuation appears in expected text
            expected_before = None
            expected_after = None
            
            # Check if punctuation appears between two words in expected text
            tokens = line_text.split()
            for i, token in enumerate(tokens):
                if punct_text in token:
                    # Punctuation is part of a word (e.g., "2021-22/172:")
                    # It should be placed with that word
                    if i > 0:
                        expected_before = tokens[i-1]
                    if i < len(tokens) - 1:
                        expected_after = tokens[i+1]
                    break
            
            # If we found context, insert punctuation in the right place
            inserted = False
            if expected_before or expected_after:
                for i, word in enumerate(sorted_regular):
                    word_text = word.get('text', '')
                    
                    # Check if this word matches the context
                    if expected_before and fuzzy_match(word_text, expected_before) > 0.8:
                        # Insert after this word
                        result = sorted_regular[:i+1] + [punct_word] + sorted_regular[i+1:]
                        inserted = True
                        break
                    elif expected_after and fuzzy_match(word_text, expected_after) > 0.8:
                        # Insert before this word
                        result = sorted_regular[:i] + [punct_word] + sorted_regular[i:]
                        inserted = True
                        break
            
            if inserted:
                break
        
        # If we couldn't place punctuation smartly, use spatial distance
        if not result:
            # Check if punctuation is close to any regular word
            for punct_word in punctuation_words:
                punct_bbox = punct_word.get('bounding_box', [])
                if not punct_bbox or len(punct_bbox) < 8:
                    continue
                
                punct_center = get_bbox_center(punct_bbox)
                
                # Find closest regular word
                min_distance = float('inf')
                closest_idx = 0
                
                for i, reg_word in enumerate(sorted_regular):
                    reg_bbox = reg_word.get('bounding_box', [])
                    if not reg_bbox or len(reg_bbox) < 8:
                        continue
                    
                    distance = calculate_distance(punct_bbox, reg_bbox)
                    
                    if distance < min_distance:
                        min_distance = distance
                        closest_idx = i
                
                # If punctuation is far (> 1.0 units), it's probably misplaced - skip it
                if min_distance > 1.0:
                    logger.debug(f"Skipping far punctuation '{punct_word.get('text', '')}' (distance: {min_distance:.2f})")
                    continue
                
                # Insert punctuation near closest word
                # Decide before/after based on spatial position
                punct_x = punct_center[0]
                closest_x = get_bbox_center(sorted_regular[closest_idx].get('bounding_box', []))[0]
                
                if is_rotated:
                    # For rotated, compare Y positions
                    punct_y = punct_center[1]
                    closest_y = get_bbox_center(sorted_regular[closest_idx].get('bounding_box', []))[1]
                    if punct_y > closest_y:  # Punctuation is below (comes before in reading order)
                        result = sorted_regular[:closest_idx] + [punct_word] + sorted_regular[closest_idx:]
                    else:
                        result = sorted_regular[:closest_idx+1] + [punct_word] + sorted_regular[closest_idx+1:]
                else:
                    # For normal, compare X positions
                    if punct_x < closest_x:  # Punctuation is to the left
                        result = sorted_regular[:closest_idx] + [punct_word] + sorted_regular[closest_idx:]
                    else:
                        result = sorted_regular[:closest_idx+1] + [punct_word] + sorted_regular[closest_idx+1:]
                
                break
        
        # If still no result, just append punctuation at the end
        if not result:
            result = sorted_regular + punctuation_words
        
        return result


    # ============================================
    # FIND ALL CANDIDATES FOR EACH LINE
    # ============================================

    def find_all_candidates_for_line(line_text: str, word_pool: List[Dict], 
                                    fuzzy_threshold: float = 0.80,
                                    is_rotated: bool = False) -> List[Dict]:
        """
        Find ALL possible word matches for a line_text in word_pool
        Works for both normal and rotated pages (NO coordinate transformation!)
        """
        
        tokens = line_text.split()
        if not tokens:
            return []
        
        logger.debug(f"Finding candidates for: '{line_text}' ({len(tokens)} tokens, rotated={is_rotated})")
        
        candidates = []
        
        for start_idx in range(len(word_pool)):
            matched_words = []
            used_indices = set()
            
            for token in tokens:
                best_match = None
                best_similarity = 0
                best_idx = -1
                best_distance = float('inf')
                
                # Search forward from current position
                for idx in range(start_idx, min(start_idx + 100, len(word_pool))):
                    if idx in used_indices:
                        continue
                    
                    word = word_pool[idx]
                    if not word or not isinstance(word, dict):
                        continue
                        
                    word_text = word.get('text', '').strip()
                    if not word_text:
                        continue
                    
                    similarity = fuzzy_match(token, word_text)
                    
                    if similarity >= fuzzy_threshold:
                        # If we already have matched words, prefer words that are CLOSE to them
                        if matched_words:
                            # Calculate distance to last matched word
                            last_bbox = matched_words[-1].get('bounding_box', [])
                            curr_bbox = word.get('bounding_box', [])
                            
                            if last_bbox and curr_bbox and len(last_bbox) >= 8 and len(curr_bbox) >= 8:
                                distance = calculate_distance(last_bbox, curr_bbox)
                                
                                # Prefer closer words, especially for punctuation
                                if is_standalone_punctuation(word_text):
                                    # For punctuation, strongly prefer close matches
                                    if distance < 1.0 and (similarity > best_similarity or 
                                                        (similarity == best_similarity and distance < best_distance)):
                                        best_match = word
                                        best_similarity = similarity
                                        best_idx = idx
                                        best_distance = distance
                                else:
                                    # For regular words, prefer high similarity, but consider distance
                                    if similarity > best_similarity or (similarity == best_similarity and distance < best_distance):
                                        best_match = word
                                        best_similarity = similarity
                                        best_idx = idx
                                        best_distance = distance
                            else:
                                # No bbox info, use similarity only
                                if similarity > best_similarity:
                                    best_match = word
                                    best_similarity = similarity
                                    best_idx = idx
                        else:
                            # First word, use similarity only
                            if similarity > best_similarity:
                                best_match = word
                                best_similarity = similarity
                                best_idx = idx
                
                if best_match:
                    matched_words.append(best_match)
                    used_indices.add(best_idx)
                else:
                    break
            
            # Check if we matched all tokens
            if len(matched_words) == len(tokens):
                # Check if on same line (different for rotated vs normal)
                y_tolerance = 0.3 if len(matched_words) == 1 else 0.2
                x_tolerance = 0.3 if len(matched_words) == 1 else 0.2
                
                if is_rotated:
                    on_same_line = are_words_on_same_line_rotated(matched_words, x_tolerance=x_tolerance)
                else:
                    on_same_line = are_words_on_same_line(matched_words, y_tolerance=y_tolerance)
                
                if on_same_line:
                    # Sort based on page rotation - use smart sorting for punctuation
                    matched_words_sorted = smart_sort_words(matched_words, line_text, is_rotated)
                    
                    # Build match info
                    matched_text = ' '.join([w.get('text', '') for w in matched_words_sorted])
                    line_bbox = merge_bboxes([w['bounding_box'] for w in matched_words_sorted], padding=0.01)
                    
                    if line_bbox:
                        avg_confidence = sum(w.get('confidence', 0) for w in matched_words_sorted) / len(matched_words_sorted)
                        similarity = fuzzy_match(line_text, matched_text)
                        
                        candidate = {
                            'matched_text': matched_text,
                            'field_value': line_text,
                            'bounding_box': line_bbox,
                            'bounding_page': matched_words_sorted[0].get('bounding_page', 1),
                            'match_confidence': similarity * 100,
                            'coordinate_confidence': similarity * 100,
                            'match_type': 'word_refined_rotated' if is_rotated else 'word_refined',
                            'ocr_confidence': avg_confidence,
                            'word_count': len(matched_words_sorted),
                            'start_idx': start_idx,
                            'words': matched_words_sorted
                        }
                        
                        candidates.append(candidate)
        
        logger.info(f"Found {len(candidates)} candidates for '{line_text}'")
        return candidates


    # ============================================
    # SPATIAL CLUSTERING - FIND BEST GROUP
    # ============================================

    def find_best_spatial_cluster(expected_lines: List[str], word_pool: List[Dict],
                              fuzzy_threshold: float = 0.80,
                              is_rotated: bool = False) -> List[Dict]:
        """
        Find the best spatial cluster of lines
        Works for both normal and rotated pages
        """
       
        logger.info(f"Finding best spatial cluster for {len(expected_lines)} lines (rotated={is_rotated})")
       
        # Find all candidates for each line
        all_candidates = {}
       
        for line_text in expected_lines:
            candidates = find_all_candidates_for_line(line_text, word_pool, fuzzy_threshold, is_rotated)
           
            if not candidates:
                logger.warning(f"No candidates found for: '{line_text}'")
                return []
           
            all_candidates[line_text] = candidates
            logger.info(f"  '{line_text}': {len(candidates)} candidates")
       
        # Try to find best combination
        best_cluster = None
        best_score = -1
        best_total_distance = float('inf')
       
        first_line = expected_lines[0]
       
        for attempt_num, first_candidate in enumerate(all_candidates[first_line]):
            cluster = [first_candidate]
            current_used_words = set()
            cluster_total_distance = 0
           
            # Mark words from first candidate as used
            for word in first_candidate.get('words', []):
                word_id = id(word)
                current_used_words.add(word_id)
           
            for line_idx, line_text in enumerate(expected_lines[1:], start=2):
                candidates = all_candidates.get(line_text, [])
               
                if not candidates:
                    break
               
                # Find candidate closest to current cluster AND doesn't reuse words
                best_candidate = None
                best_distance = float('inf')
               
                for cand_idx, candidate in enumerate(candidates):
                    # Check if this candidate reuses any words from previous lines
                    candidate_word_ids = set(id(w) for w in candidate.get('words', []))
                   
                    if candidate_word_ids & current_used_words:
                        continue
                   
                    # ✅ CRITICAL FIX: For multi-line text, use Y-distance primarily
                    last_bbox = cluster[-1]['bounding_box']
                    curr_bbox = candidate['bounding_box']
                   
                    last_y = (last_bbox[1] + last_bbox[3] + last_bbox[5] + last_bbox[7]) / 4
                    curr_y = (curr_bbox[1] + curr_bbox[3] + curr_bbox[5] + curr_bbox[7]) / 4
                   
                    # Y-distance is primary factor for sequential lines
                    distance_to_last = abs(curr_y - last_y)
                   
                    if distance_to_last < best_distance:
                        best_distance = distance_to_last
                        best_candidate = candidate
               
                if best_candidate:
                    cluster.append(best_candidate)
                    cluster_total_distance += best_distance
                   
                    # Mark words from this candidate as used
                    for word in best_candidate.get('words', []):
                        current_used_words.add(id(word))
                else:
                    break
           
            # Check if cluster is complete
            if len(cluster) == len(expected_lines):
                score = score_cluster(cluster, expected_lines)
                avg_distance_per_line = cluster_total_distance / max(1, len(cluster) - 1)
               
                # Prioritize clusters with smaller total distance
                is_better = False
                if best_cluster is None:
                    is_better = True
                elif avg_distance_per_line < best_total_distance * 0.8:
                    is_better = True
                elif avg_distance_per_line < best_total_distance * 1.2 and score > best_score * 1.1:
                    is_better = True
               
                if is_better:
                    best_score = score
                    best_cluster = cluster
                    best_total_distance = avg_distance_per_line
       
        if best_cluster:
            logger.info(f"✓ Found best cluster with score {best_score:.2f}, avg Y-distance {best_total_distance:.4f}")
           
            # Log final cluster details
            for i, item in enumerate(best_cluster):
                if i > 0:
                    prev_y = (best_cluster[i-1]['bounding_box'][1] + best_cluster[i-1]['bounding_box'][5]) / 2
                    curr_y = (item['bounding_box'][1] + item['bounding_box'][5]) / 2
                    y_dist = abs(curr_y - prev_y)
                    logger.info(f"  Line {i+1}: '{item.get('matched_text', '')}' at Y={curr_y:.4f} (Y-distance: {y_dist:.4f})")
                else:
                    curr_y = (item['bounding_box'][1] + item['bounding_box'][5]) / 2
                    logger.info(f"  Line {i+1}: '{item.get('matched_text', '')}' at Y={curr_y:.4f}")
           
            return best_cluster
        else:
            logger.warning("No complete cluster found")
            return []
 

    def score_cluster(cluster: List[Dict], expected_lines: List[str]) -> float:
        """Score a cluster based on spatial compactness, match quality, and completeness"""
        
        if not cluster:
            return 0
        
        # Spatial compactness score
        all_bboxes = [item['bounding_box'] for item in cluster]
        merged = merge_bboxes(all_bboxes, padding=0)
        
        if not merged or len(merged) < 8:
            return 0
        
        width = max(merged[2], merged[4]) - min(merged[0], merged[6])
        height = max(merged[5], merged[7]) - min(merged[1], merged[3])
        area = width * height
        
        compactness_score = max(0, 100 - (area * 10))
        
        # Match quality score
        avg_confidence = sum(item['match_confidence'] for item in cluster) / len(cluster)
        
        # Completeness score
        completeness_score = (len(cluster) / len(expected_lines)) * 100
        
        # Combined score
        total_score = (
            compactness_score * 0.5 +
            avg_confidence * 0.3 +
            completeness_score * 0.2
        )
        
        return total_score


    # ============================================
    # FALLBACK STRATEGIES
    # ============================================

    def fallback_rotated_page_search(expected_lines: List[str], word_pool: List[Dict],
                                    fuzzy_threshold: float = 0.80) -> List[Dict]:
        """
        Fallback for rotated pages: Use rotated page logic (NO coordinate transformation!)
        """
        logger.info("FALLBACK: Trying rotated page search")
        
        # Check if page is actually rotated
        if not detect_page_rotation(word_pool):
            logger.info("Page not rotated, skipping this fallback")
            return []
        
        # Use spatial clustering with is_rotated=True
        result = find_best_spatial_cluster(expected_lines, word_pool, fuzzy_threshold, is_rotated=True)
        
        if result:
            logger.info(f"✓ Rotated page search found {len(result)} lines")
        
        return result


    def fallback_fuzzy_search(expected_lines: List[str], word_pool: List[Dict], 
                            fuzzy_threshold: float = 0.75) -> List[Dict]:
        """Fallback: Fuzzy search with punctuation stripping"""
        
        logger.info("FALLBACK: Trying fuzzy search with punctuation stripping")
        
        result_lines = []
        search_start_idx = 0
        
        for line_text in expected_lines:
            clean_line = strip_punctuation(line_text)
            
            if not clean_line:
                clean_line = line_text
            
            logger.debug(f"Searching for: '{clean_line}'")
            
            best_match = None
            best_score = 0
            best_end_idx = search_start_idx
            
            for start_idx in range(search_start_idx, len(word_pool)):
                tokens = clean_line.split()
                if not tokens:
                    continue
                
                matched_words = []
                current_idx = start_idx
                
                for token in tokens:
                    found = False
                    
                    for look_idx in range(current_idx, min(current_idx + 20, len(word_pool))):
                        word = word_pool[look_idx]
                        if not word or not isinstance(word, dict):
                            continue
                            
                        word_text = strip_punctuation(word.get('text', ''))
                        
                        if fuzzy_match(token, word_text) >= fuzzy_threshold:
                            matched_words.append(word)
                            current_idx = look_idx + 1
                            found = True
                            break
                    
                    if not found:
                        break
                
                if len(matched_words) == len(tokens):
                    y_tolerance = 0.35
                    if are_words_on_same_line(matched_words, y_tolerance=y_tolerance):
                        matched_words_sorted = sort_words_left_to_right(matched_words)
                        matched_text = ' '.join([w.get('text', '') for w in matched_words_sorted])
                        score = fuzzy_match(clean_line, matched_text)
                        
                        if score > best_score:
                            best_score = score
                            best_match = matched_words_sorted
                            best_end_idx = current_idx
            
            if best_match:
                matched_text = ' '.join([w.get('text', '') for w in best_match])
                line_bbox = merge_bboxes([w['bounding_box'] for w in best_match], padding=0.01)
                
                if line_bbox:
                    avg_confidence = sum(w.get('confidence', 0) for w in best_match) / len(best_match)
                    
                    result = {
                        'matched_text': matched_text,
                        'field_value': line_text,
                        'bounding_box': line_bbox,
                        'bounding_page': best_match[0].get('bounding_page', 1),
                        'match_confidence': best_score * 100,
                        'coordinate_confidence': best_score * 100,
                        'match_type': 'word_refined_fallback',
                        'ocr_confidence': avg_confidence,
                        'word_count': len(best_match)
                    }
                    
                    result_lines.append(result)
                    search_start_idx = best_end_idx
                    logger.info(f"✓ Fuzzy found: '{line_text}' → '{matched_text}'")
        
        return result_lines


    def fallback_expand_existing_match(best_match: Dict, expected_lines: List[str], 
                                    word_pool: List[Dict]) -> List[Dict]:
        """Fallback: Expand around existing partial match"""
        
        logger.info("FALLBACK: Trying to expand existing partial match")
        
        if not best_match or not isinstance(best_match, dict) or 'bounding_box' not in best_match:
            return []
        
        match_bbox = best_match['bounding_box']
        match_page = best_match.get('bounding_page', 1)
        
        nearby_words = []
        
        for word in word_pool:
            if not word or not isinstance(word, dict):
                continue
                
            if word.get('bounding_page') != match_page:
                continue
            
            word_bbox = word.get('bounding_box', [])
            if not word_bbox or len(word_bbox) < 8:
                continue
            
            distance = calculate_distance(match_bbox, word_bbox)
            
            if distance <= 1.0:
                nearby_words.append(word)
        
        if not nearby_words:
            logger.warning("No nearby words found")
            return []
        
        sorted_nearby = sort_words_reading_order(nearby_words)
        
        logger.info(f"Found {len(sorted_nearby)} nearby words")
        
        return fallback_fuzzy_search(expected_lines, sorted_nearby, fuzzy_threshold=0.70)


    # ============================================
    # MAIN REFINER
    # ============================================

    def refine_coordinate_response(field_value: str, matches: List[Dict], 
                                best_match: Optional[Dict], 
                                word_ocr_data: List[Dict]) -> Dict:
        """
        Main refiner function with spatial clustering + rotated page support
        """
        
        logger.info("=" * 60)
        logger.info("OCR REFINER - Starting")
        logger.info(f"Field value: '{field_value}'")
        logger.info(f"Matches: {len(matches) if matches else 0}")
        logger.info(f"Best match: {best_match is not None}")
        logger.info("=" * 60)
        
        if not word_ocr_data:
            logger.error("No word_ocr_data!")
            return {'best_match': best_match, 'matches': matches if matches else []}
        
        # Safety check
        if not field_value:
            logger.error("No field_value!")
            return {'best_match': best_match, 'matches': matches if matches else []}
        
        # Skip if TOTAL field_value length is too long (>200 chars)
        if len(field_value) > 200:
            logger.info(f"Field value too long ({len(field_value)} chars > 200) - skipping refinement")
            return {'best_match': best_match, 'matches': matches if matches else []}
        
        # Parse lines
        expected_lines = [line.strip() for line in field_value.split('\n') if line.strip()]
        
        if not expected_lines:
            logger.error("No expected lines after parsing!")
            return {'best_match': best_match, 'matches': matches if matches else []}
        
        logger.info(f"Processing {len(expected_lines)} lines")
        
        # Get anchor page
        anchor_page = None
        if best_match and isinstance(best_match, dict):
            anchor_page = best_match.get('bounding_page', 1)
        
        # Filter to anchor page
        if anchor_page:
            word_pool = [w for w in word_ocr_data if w and isinstance(w, dict) and w.get('bounding_page') == anchor_page]
            logger.info(f"Using {len(word_pool)} words from page {anchor_page}")
        else:
            word_pool = [w for w in word_ocr_data if w and isinstance(w, dict)]
            if word_pool:
                anchor_page = word_pool[0].get('bounding_page', 1)
        
        if not word_pool:
            logger.error("No valid words in word_pool!")
            return {'best_match': best_match, 'matches': matches if matches else []}
        
        # Sort word pool
        sorted_word_pool = sort_words_reading_order(word_pool)
        logger.info(f"Sorted {len(sorted_word_pool)} words in reading order")
        
        # PRIMARY: Normal spatial clustering
        result_lines = find_best_spatial_cluster(expected_lines, sorted_word_pool, fuzzy_threshold=0.80, is_rotated=False)
        
        # FALLBACK LOGIC
        if not result_lines:
            logger.warning("❌ Spatial clustering failed - trying fallback strategies")
            
            # Fallback 1: Rotated page search
            logger.info("Trying rotated page fallback...")
            result_lines = fallback_rotated_page_search(expected_lines, sorted_word_pool, fuzzy_threshold=0.80)
            
            if not result_lines:
                # Fallback 2: Fuzzy search
                logger.info("Trying fuzzy search fallback...")
                result_lines = fallback_fuzzy_search(expected_lines, sorted_word_pool, fuzzy_threshold=0.75)
                
                if not result_lines and best_match:
                    # Fallback 3: Expand existing match
                    logger.warning("Trying to expand existing match...")
                    result_lines = fallback_expand_existing_match(best_match, expected_lines, sorted_word_pool)
            
            if not result_lines:
                logger.error("❌ ALL FALLBACKS FAILED - returning original")
                return {
                    'best_match': best_match, 
                    'matches': matches if matches else []
                }
        
        # Build final result
        if len(result_lines) == 1:
            refined_best_match = result_lines[0]
        else:
            all_bboxes = [line.get('bounding_box') for line in result_lines if line.get('bounding_box')]
            
            if not all_bboxes:
                logger.error("No valid bboxes in result_lines!")
                return {
                    'best_match': best_match,
                    'matches': matches if matches else []
                }
            
            merged_bbox = merge_bboxes(all_bboxes, padding=0.02)
            
            combined_text = '\n'.join([line['matched_text'] for line in result_lines])
            avg_confidence = sum(line['ocr_confidence'] for line in result_lines) / len(result_lines)
            page = result_lines[0]['bounding_page']
            
            refined_best_match = {
                'matched_text': combined_text,
                'field_value': field_value,
                'bounding_box': merged_bbox,
                'bounding_page': page,
                'match_confidence': 85,
                'coordinate_confidence': 85,
                'match_type': 'word_refined_multiline',
                'ocr_confidence': avg_confidence,
                'line_count': len(result_lines),
                'lines': result_lines
            }
        
        logger.info("=" * 60)
        logger.info(f"✅ SUCCESS - {len(result_lines)}/{len(expected_lines)} lines found")
        logger.info(f"Result: '{refined_best_match.get('matched_text', '')[:100]}...'")
        logger.info("=" * 60)
        
        return {
            'best_match': refined_best_match,
            'matches': result_lines
        }


    # ============================================
    # WRAPPER FOR API RESPONSE
    # ============================================

    def process_coordinate_response(response_data: Dict, word_ocr_data: List[Dict]) -> Dict:
        """Process full API response"""
        
        if not response_data.get('success'):
            return response_data
        
        field_value = response_data.get('field_value', '')
        matches = response_data.get('matches', [])
        best_match = response_data.get('best_match')
        
        if not field_value or not word_ocr_data:
            return response_data
        
        try:
            refined = refine_coordinate_response(field_value, matches, best_match, word_ocr_data)
            
            response_data['best_match'] = refined['best_match']
            response_data['matches'] = refined['matches']
            response_data['total_matches'] = len(refined['matches'])
            response_data['message'] = f"Refined match for \"{field_value[:50]}...\""
            
            logger.info("✅ Response refined successfully")
        
        except Exception as e:
            logger.error(f"Refinement error: {e}", exc_info=True)
        
        return response_data
    @app.route('/api/search_field_coordinates', methods=['POST'])
    @timing_aspect
    def search_field_coordinates():
        """Search for field coordinates in existing OCR data with absolute accuracy"""
        try:
            logger.info("SEARCH: === COORDINATE SEARCH API CALLED ===")
            import os
            import json
            import pickle
            import tempfile
            import time
            
            data = request.get_json()
            field_value = data.get('exact_text')
            if not field_value:  
                field_value = data.get('field_value', '').strip()
            search_mode = data.get('search_mode', 'exact').lower()
            bounding_page = data.get('boundingpage', None)

            logger.info(f" Payload bounding_page: {bounding_page}")
            logger.info(f"data payload: {data}")

            # ✅ FIX: Normalize current_page always to a list of ints
            if bounding_page is None:
                current_page = []
            elif isinstance(bounding_page, list):
                current_page = [int(p) for p in bounding_page if isinstance(p, (int, str)) and str(p).isdigit()]
            else:
                current_page = [int(bounding_page)] if str(bounding_page).isdigit() else []
            if current_page:
                logger.info(f" Page-specific search requested: Page {current_page}")
            else:
                logger.info(f"Multi-page search (all pages)")

            # Get OCR data from session
            ocr_data = session.get('current_ocr_data', [])
            logger.info(f" Session OCR data check: Found {len(ocr_data) if ocr_data else 0} entries")

            # Debug session keys
            session_keys = list(session.keys())
            logger.info(f" Available session keys: {session_keys}")

            # Log page distribution in OCR data
            if ocr_data:
                page_counts = {}
                for entry in ocr_data:
                    page = entry.get('bounding_page', 'unknown')
                    page_counts[page] = page_counts.get(page, 0) + 1
                logger.info(f"ANALYTICS: OCR data page distribution: {dict(sorted(page_counts.items()))}")
            if not ocr_data:
                # Try alternative session keys
                alt_ocr_data = session.get('ocr_data', [])
                logger.info(f"SEARCH: Checking alternative 'ocr_data' key: Found {len(alt_ocr_data) if alt_ocr_data else 0} entries")

                if alt_ocr_data:
                    ocr_data = alt_ocr_data
                    logger.info("SUCCESS:Using alternative OCR data from 'ocr_data' session key")
                else:
                    # Try loading from temporary file (workaround for session size limits)
                    ocr_session_id = session.get('ocr_session_id')
                    logger.info(f"SEARCH: Looking for OCR session ID: {ocr_session_id}")

                    if ocr_session_id:
                        import tempfile as temp_module
                        import pickle
                        ocr_temp_file = os.path.join(temp_module.gettempdir(), f"ocr_data_{ocr_session_id}.pkl")

                        try:
                            if os.path.exists(ocr_temp_file):
                                with open(ocr_temp_file, 'rb') as f:
                                    ocr_data = pickle.load(f)
                                logger.info(f"SUCCESS:Loaded OCR data from temp file: {len(ocr_data)} entries")

                            else:
                                logger.warning(f"ERROR: OCR temp file not found: {ocr_temp_file}")
                        except Exception as e:
                            logger.error(f"ERROR: Failed to load OCR data from temp file: {e}")
                    else:
                        # Fallback: Try to find the most recent OCR temp file
                        logger.info("SEARCH: No OCR session ID found, searching for recent OCR temp files...")
                        import tempfile as temp_module
                        import pickle
                        import glob

                        try:
                            temp_dir = temp_module.gettempdir()
                            ocr_files = glob.glob(os.path.join(temp_dir, "ocr_data_*.pkl"))

                            if ocr_files:
                                # Sort by creation time, get the most recent
                                ocr_files.sort(key=lambda x: os.path.getctime(x), reverse=True)
                                most_recent_file = ocr_files[0]

                                # Check if file is recent (less than 10 minutes old)
                                file_age = time.time() - os.path.getctime(most_recent_file)
                                if file_age < 600:  # 10 minutes
                                    logger.info(f"SEARCH: Trying most recent OCR file: {most_recent_file} (age: {file_age:.1f}s)")

                                    with open(most_recent_file, 'rb') as f:
                                        ocr_data = pickle.load(f)
                                    logger.info(f"SUCCESS:Loaded OCR data from recent temp file: {len(ocr_data)} entries")

                                else:
                                    logger.warning(f"ERROR: Most recent OCR file is too old: {file_age:.1f}s")
                            else:
                                logger.warning("ERROR: No OCR temp files found")
                        except Exception as e:
                            logger.error(f"ERROR: Failed to search for recent OCR temp files: {e}")

                    if not ocr_data:
                        logger.warning("ERROR: No OCR data found in session under any key")
                        return jsonify({
                            'success': False,
                            'message': 'No OCR data available. Please process a document first.',
                            'matches': [],
                            'debug_info': {
                                'session_keys': session_keys,
                                'current_ocr_data_length': len(session.get('current_ocr_data', [])),
                                'ocr_data_length': len(session.get('ocr_data', [])),
                                'ocr_session_id': session.get('ocr_session_id', 'Not found'),
                                'temp_file_attempted': ocr_session_id is not None
                            }
                        }), 400

            # Use the search_text_in_ocr helper function
            # Run search
            if current_page and ocr_data:
                original_count = len(ocr_data)
                ocr_data = [
                    entry for entry in ocr_data
                    if int(entry.get('bounding_page', 0)) in current_page
                ]
                logger.info(f"SEARCH: Page filtering: {original_count} -> {len(ocr_data)} entries (Pages {current_page})")
            matches = search_text_in_ocr(field_value, ocr_data, search_mode)
            logger.info(f"SAVE: Search complete: Found {len(matches)} matches")
            # Prepare response in format expected by frontend
            best_match = matches[0] if matches else None

            # Load word data
            word_ocr_data = session.get('word_ocr_data', [])
            if not word_ocr_data:
                ocr_session_id = session.get('ocr_session_id')
                temp_dir = tempfile.gettempdir()

                if ocr_session_id:
                    word_temp_file = os.path.join(temp_dir, f"word_data_{ocr_session_id}.pkl")
                    if os.path.exists(word_temp_file):
                        try:
                            with open(word_temp_file, 'rb') as f:
                                word_ocr_data = pickle.load(f)
                            logger.info(f"Loaded words: {len(word_ocr_data)}")
                        except Exception as e:
                            logger.error(f"Load words error: {e}")

                if not word_ocr_data:
                    try:
                        word_files = [f for f in os.listdir(temp_dir) if f.startswith("word_data_") and f.endswith(".pkl")]
                        if word_files:
                            word_files = [os.path.join(temp_dir, f) for f in word_files]
                            word_files.sort(key=os.path.getctime, reverse=True)
                            recent_file = word_files[0]
                            if time.time() - os.path.getctime(recent_file) < 600:
                                with open(recent_file, 'rb') as f:
                                    word_ocr_data = pickle.load(f)
                                logger.info(f"Loaded recent words: {len(word_ocr_data)}")
                    except Exception as e:
                        logger.error(f"Load recent words error: {e}")
            

             # ✅ Apply page filtering for word_data (just like OCR)
            if current_page and word_ocr_data:
                original_word_count = len(word_ocr_data)
                word_ocr_data = [
                    entry for entry in word_ocr_data
                    if int(entry.get('bounding_page', 0)) in current_page
                ]
                logger.info(f"SEARCH: Page filtering (word_ocr_data): {original_word_count} -> {len(word_ocr_data)} entries (Pages {current_page})")
            
              
            response =  {
                'success': True,
                'message': f'Found {len(matches)} matches for "{field_value}"',
                'field_value': field_value,
                'search_mode': search_mode,
                'matches': matches,
                'best_match': best_match,
                'total_matches': len(matches),
                'total_ocr_entries': len(ocr_data)
            } 
            logger.error(f"response value:{response}")
            logger.error(f"=== BEFORE REFINE ===")
            logger.error(f"word_ocr_data length: {len(word_ocr_data)}")
            logger.error(f"word_ocr_data sample: {word_ocr_data[:2] if word_ocr_data else 'EMPTY'}")
            logger.error(f"best_match: {best_match}")

            refined_response = process_coordinate_response(response, word_ocr_data)

            # logger.error(f"=== AFTER REFINE ===")
            # logger.error(f"refined best_match type: {refined_response['best_match'].get('match_type')}")
            # logger.error(f"refined matched_text: {refined_response['best_match'].get('matched_text')}")
            return jsonify(refined_response)
             
        except Exception as e:
            logger.error(f"ERROR: Error in coordinate search API: {e}")
            return jsonify({
                'success': False,
                'message': f'Search error: {str(e)}',
                'matches': []
            }), 500
        
