    @app.route('/api/document_entity_maintenance', methods=['POST'])
    @timing_aspect
    def create_document_entity_mapping():
        """Create a new document entity mapping"""
        try:
            mapping_data = request.get_json()

            # ---- 1. Validate required fields ----
            required_fields = ['documentId', 'documentCategoryId', 'entityId', 'dataCategoryId', 'fieldType']
            missing = [f for f in required_fields if not mapping_data.get(f)]
            if missing:
                return jsonify({'success': False, 'message': f"Missing required fields: {', '.join(missing)}"}), 400

            document_id = mapping_data['documentId']

            # ---- 2. Load existing data ----
            doc_data = _load_document_entity_mapping_by_document(document_id)
            doc_entity_data = _load_document_entity_maintenance_by_document(document_id)

            # ---- 3. Generate new IDs ----
            def _next_id(loader):
                all_data = loader()
                ids = [int(m['id']) for m in all_data.get('mappings', []) if str(m.get('id', '')).isdigit()]
                return str(max(ids, default=0) + 1)

            new_id = _next_id(_load_document_entity_mappings)
            new_entity_id = _next_id(_load_document_entity_maintenance_mappings)

            # ---- 4. Build mapping dict once ----
            base_mapping = {
                'documentId': mapping_data['documentId'],
                'documentName': mapping_data.get('documentName', ''),
                'documentCategoryId': mapping_data['documentCategoryId'],
                'documentCategoryName': mapping_data.get('documentCategoryName', ''),
                'entityId': mapping_data['entityId'],
                'entityName': mapping_data.get('entityName', ''),
                'mappingFormField': mapping_data.get('mappingFormField', ''),
                'mappingFormDescription': mapping_data.get('mappingFormDescription', ''),
                'dataCategoryId': mapping_data['dataCategoryId'],
                'dataCategoryValue': mapping_data.get('dataCategoryValue', ''),
                'fieldType': mapping_data['fieldType']
            }

            new_mapping = dict(base_mapping, id=new_id)
            new_entity_mapping = dict(base_mapping, id=new_entity_id)

            # ---- 5. Append to doc data ----
            for d, name in [(doc_data, 'documentName'), (doc_entity_data, 'documentName')]:
                if not d.get(name):
                    d[name] = mapping_data.get('documentName', '')

            doc_data.setdefault('mappings', []).append(new_mapping)
            doc_entity_data.setdefault('mappings', []).append(new_entity_mapping)

            # ---- 6. Save both ----
            if (_save_document_entity_mapping_by_document(document_id, doc_data) and
                    _save_document_entity_maintenance_mapping_by_document(document_id, doc_entity_data)):
                return jsonify({'success': True, 'mapping': new_entity_mapping}), 201

            return jsonify({'success': False, 'message': 'Failed to save mapping'}), 500

        except Exception as e:
            logger.error(f"Error creating document entity mapping: {e}")
            return jsonify({'success': False, 'message': str(e)}), 500

    @app.route('/api/document_entity_maintenance/<mapping_id>', methods=['PUT'])
    @timing_aspect
    def update_document_entity_mapping(mapping_id):
        """Update a document entity mapping and sync with common JSON"""
        try:
            mapping_data = request.get_json()
            document_id = mapping_data.get('documentId')

            if not document_id:
                return jsonify({'success': False, 'message': 'Missing documentId'}), 400

            # Load the document-specific file
            doc_data = _load_document_entity_mapping_by_document(document_id)

            found = False
            for i, mapping in enumerate(doc_data.get('mappings', [])):
                if mapping.get('id') == mapping_id:
                    updated_mapping = {
                        'id': mapping_id,
                        'documentId': mapping_data.get('documentId'),
                        'documentName': mapping_data.get('documentName', ''),
                        'documentCategoryId': mapping_data.get('documentCategoryId'),
                        'documentCategoryName': mapping_data.get('documentCategoryName', ''),
                        'entityId': mapping_data.get('entityId'),
                        'entityName': mapping_data.get('entityName', ''),
                        'mappingFormField': mapping_data.get('mappingFormField', ''),
                        'mappingFormDescription': mapping_data.get('mappingFormDescription', ''),
                        'dataCategoryId': mapping_data.get('dataCategoryId'),
                        'dataCategoryValue': mapping_data.get('dataCategoryValue', ''),
                        'fieldType': mapping_data.get('fieldType')
                    }

                    # Update document-specific mapping
                    doc_data['mappings'][i] = updated_mapping
                    found = True

                    # Save document JSON
                    if not _save_document_entity_mapping_by_document(document_id, doc_data):
                        return jsonify({'success': False, 'message': 'Failed to save mapping'}), 500

                    # ✅ Update the common JSON (shared helper)
                    _update_or_delete_common_mapping(updated_mapping, operation='update')

                    return jsonify({'success': True, 'mapping': updated_mapping}), 200

            if not found:
                return jsonify({'success': False, 'message': f'Mapping ID {mapping_id} not found'}), 404

        except Exception as e:
            logger.error(f"Error updating document entity mapping {mapping_id}: {e}")
            return jsonify({'success': False, 'message': str(e)}), 500


    @app.route('/api/document_entity_maintenance/<mapping_id>', methods=['DELETE'])
    @timing_aspect
    def delete_document_entity_mapping(mapping_id):
        """Delete a document entity mapping and remove from common JSON"""
        try:
            # Need to find which document this mapping belongs to
            all_data = _load_document_entity_mappings()
            document_id = None
            mapping_to_delete = None

            for mapping in all_data.get('mappings', []):
                if mapping.get('id') == mapping_id:
                    document_id = mapping.get('documentId')
                    mapping_to_delete = mapping
                    break

            if not document_id:
                return jsonify({'success': False, 'message': 'Mapping not found'}), 404

            # Load the specific document JSON
            doc_data = _load_document_entity_mapping_by_document(document_id)

            # Remove the mapping
            original_length = len(doc_data.get('mappings', []))
            doc_data['mappings'] = [m for m in doc_data.get('mappings', []) if m.get('id') != mapping_id]

            if len(doc_data['mappings']) < original_length:
                if _save_document_entity_mapping_by_document(document_id, doc_data):
                    # ✅ Delete from common JSON (shared helper)
                    if mapping_to_delete:
                        _update_or_delete_common_mapping(mapping_to_delete, operation='delete')

                    return jsonify({'success': True, 'message': 'Mapping deleted successfully'}), 200
                else:
                    return jsonify({'success': False, 'message': 'Failed to save changes'}), 500
            else:
                return jsonify({'success': False, 'message': 'Mapping not found'}), 404

        except Exception as e:
            logger.error(f"Error deleting document entity mapping {mapping_id}: {e}")
            return jsonify({'success': False, 'message': str(e)}), 500

