    def organize_ocr_data_by_page(text_data):
        """Organize OCR data by page number with enhanced debugging"""
        logger.info(f"ANALYTICS: === ORGANIZING OCR DATA BY PAGE ===")
        logger.info(f"Input: {len(text_data)} OCR entries")

        # Debug: Check page distribution in raw data
        page_counts = {}
        missing_page_count = 0

        for i, entry in enumerate(text_data):
            page = entry.get("bounding_page", None)
            if page is None:
                missing_page_count += 1
                logger.warning(f"Entry {i}: Missing bounding_page field - {entry.get('text', '')[:30]}...")
                page = 1  # Default fallback

            page_counts[page] = page_counts.get(page, 0) + 1

        logger.info(f"ANALYTICS: Page distribution in raw OCR data:")
        for page in sorted(page_counts.keys()):
            logger.info(f"   Page {page}: {page_counts[page]} entries")

        if missing_page_count > 0:
            logger.warning(f"WARNINGS: Found {missing_page_count} entries without page information")

        # Organize by page
        pages = defaultdict(list)
        for entry in text_data:
            page = entry.get("bounding_page", 1)
            pages[page].append(entry)

        organized_pages = [pages[k] for k in sorted(pages)]
        logger.info(f"SUCCESS:Organized into {len(organized_pages)} pages")

        # Debug: Log sample from each page
        for page_idx, page_data in enumerate(organized_pages):
            actual_page = page_idx + 1
            logger.info(f"   Page {actual_page}: {len(page_data)} entries")
            if page_data:
                sample_text = page_data[0].get('text', '')[:30]
                logger.info(f"      Sample: '{sample_text}...'")

        return organized_pages

    def calculate_text_token_count(text, model_name="gpt-3.5-turbo"):
        enc = tiktoken.encoding_for_model(model_name)
        return len(enc.encode(text))

    def format_ocr_data_for_llm_prompt(ocr_data):
        formatted = ""
        for i, entry in enumerate(ocr_data):
            text = entry.get("text", "").replace("\n", " ")
            box = entry.get("bounding_box", [])
            page = entry.get("bounding_page", 0)
            formatted += f"{i + 1}. Text: \"{text}\"\n   Box: {box}, Page: {page}\n"
        return formatted

    def parse_json_from_llm_response(text):
        try:
            json_str = re.search(r'\{[\s\S]+\}', text).group()
            return json.loads(json_str)
        except Exception as e:
            logging.error(f"Could not parse JSON from LLM response: {e}")
            return None

    def identify_document_type(extracted_text):
        # Use the new document classifier for better accuracy
        classification = document_classifier.classify_document(extracted_text)
        doc_type = classification.get("document_type", "unknown").lower().replace(" ", "_")
        # Map to expected format
        if "guarantee" in doc_type:
            return "bank_guarantee"
        elif "letter" in doc_type and "credit" in doc_type:
            return "letter_of_credit"
        return doc_type

    def load_document_analysis_prompt(document_type, extracted_text, product_name=None, function_name=None):
        # Use document classifier to get fields dynamically
        field_list, field_definitions = document_classifier.get_document_fields(
            document_type, product_name, function_name
        )

        # If we have function-specific fields, use those; otherwise use document fields
        if field_definitions:
            # Format fields with descriptions
            formatted_fields = "\n".join([
                f"- {field}: {desc}" for field, desc in field_definitions.items()
            ])
        else:
            # Fallback to simple field list
            formatted_fields = "\n".join([f"- {field}" for field in field_list])
        return f"""
    Analyze the following OCR-extracted text and extract key details for a {document_type} document.

    OCR Text:
    {extracted_text}

    Extract the following details:
    {formatted_fields}

    ### Extraction Rules:
    - For letter_of_credit: Do not return "null" for missing fields; omit them or leave value empty.
    - For bank_guarantee: Return "null" for missing field values.
    - Format all dates as "YYYY-MM-DD".
    - Return numeric values for amounts/currency (no symbols).
    - Assign a confidence score (0–100%) for each field based on OCR clarity and keyword proximity.
    - Include bounding_box and bounding_page if available.

    ### Expected JSON Output:
    {{
      "document_type": "{document_type}",
      "extracted_fields": {{
        "<Field Name>": {{
          "value": "<extracted_value>",
          "desc": "<field description>",
          "confidence": <score>,
          "bounding_box": [<x1>, <y1>, <x2>, <y2>],
          "bounding_page": <page_number>
        }}
      }},
      "confidence_score": <overall_score>
    }}
    """

    def aggregate_extracted_fields(extraction_results: List[Dict], strategy: str = "union", confidence_threshold: int = 70) -> Dict:
        """
        Aggregate multiple extraction results into a single consolidated result.

        Args:
            extraction_results: List of extraction result dictionaries from parallel calls
            strategy: Aggregation strategy - "union", "intersection", or "majority"
            confidence_threshold: Minimum confidence to include a field

        Returns:
            Aggregated extraction result with merged fields
        """
        logger.info(f"🔀 Aggregating {len(extraction_results)} extraction results using '{strategy}' strategy")

        if not extraction_results:
            return {}

        # Initialize aggregated result with first successful result as base
        aggregated = None
        for result in extraction_results:
            if result and 'extracted_fields' in result:
                aggregated = {
                    'page_number': result.get('page_number', 1),
                    'classification': result.get('classification', {}),
                    'extracted_fields': {},
                    'confidence_score': 0,
                    'mandatory_fields_found': 0,
                    'total_mandatory_fields': result.get('total_mandatory_fields', 0),
                    'extraction_completeness': 0,
                    'aggregation_metadata': {
                        'total_attempts': len(extraction_results),
                        'successful_attempts': sum(1 for r in extraction_results if r and 'extracted_fields' in r),
                        'strategy': strategy,
                        'confidence_threshold': confidence_threshold
                    }
                }
                break

        if not aggregated:
            logger.error("❌ No valid extraction results to aggregate")
            return {}

        # Collect all fields from all results
        field_occurrences = {}  # {field_name: [{'value': val, 'confidence': conf, 'bounding_box': box}, ...]}

        for result in extraction_results:
            if not result or 'extracted_fields' not in result:
                continue

            for field_name, field_data in result['extracted_fields'].items():
                if not isinstance(field_data, dict):
                    continue

                confidence = field_data.get('confidence', 0)
                value = field_data.get('value', '')

                # Skip if below confidence threshold or empty value
                if confidence < confidence_threshold or not value:
                    continue

                if field_name not in field_occurrences:
                    field_occurrences[field_name] = []

                field_occurrences[field_name].append({
                    'value': value,
                    'confidence': confidence,
                    'bounding_box': field_data.get('bounding_box', [0, 0, 0, 0]),
                    'bounding_page': field_data.get('bounding_page', 1)
                })

        logger.info(f"📊 Found {len(field_occurrences)} unique fields across all attempts")

        # Apply aggregation strategy
        if strategy == "union":
            # Union: Include all fields found in any attempt (take highest confidence occurrence)
            for field_name, occurrences in field_occurrences.items():
                # Sort by confidence and take the highest
                best_occurrence = max(occurrences, key=lambda x: x['confidence'])
                aggregated['extracted_fields'][field_name] = best_occurrence
                logger.debug(f"   ✓ {field_name}: {len(occurrences)} occurrences, using highest confidence")

        elif strategy == "intersection":
            # Intersection: Only include fields found in ALL attempts
            required_count = aggregated['aggregation_metadata']['successful_attempts']
            for field_name, occurrences in field_occurrences.items():
                if len(occurrences) >= required_count:
                    # Take the occurrence with highest confidence
                    best_occurrence = max(occurrences, key=lambda x: x['confidence'])
                    aggregated['extracted_fields'][field_name] = best_occurrence
                    logger.debug(f"   ✓ {field_name}: Found in all {required_count} attempts")
                else:
                    logger.debug(f"   ✗ {field_name}: Only in {len(occurrences)}/{required_count} attempts (skipped)")

        elif strategy == "majority":
            # Majority: Include fields found in 50%+ of attempts
            required_count = aggregated['aggregation_metadata']['successful_attempts'] / 2
            for field_name, occurrences in field_occurrences.items():
                if len(occurrences) >= required_count:
                    # For majority voting, we could:
                    # Option 1: Take highest confidence
                    # Option 2: Take most common value
                    # Let's use Option 1 for now
                    best_occurrence = max(occurrences, key=lambda x: x['confidence'])
                    aggregated['extracted_fields'][field_name] = best_occurrence
                    logger.debug(f"   ✓ {field_name}: Found in {len(occurrences)} attempts (majority)")
                else:
                    logger.debug(f"   ✗ {field_name}: Only in {len(occurrences)} attempts (below majority)")

        # Calculate aggregate metrics
        total_fields = len(aggregated['extracted_fields'])
        aggregated['confidence_score'] = (
            sum(f['confidence'] for f in aggregated['extracted_fields'].values()) / total_fields
            if total_fields > 0 else 0
        )

        # Count mandatory fields (assuming fields with high confidence or specific naming pattern)
        aggregated['mandatory_fields_found'] = sum(
            1 for f in aggregated['extracted_fields'].values()
            if f.get('confidence', 0) >= 85
        )

        if aggregated['total_mandatory_fields'] > 0:
            aggregated['extraction_completeness'] = int(
                (aggregated['mandatory_fields_found'] / aggregated['total_mandatory_fields']) * 100
            )

        logger.info(f"✅ Aggregation complete: {total_fields} fields, avg confidence: {aggregated['confidence_score']:.1f}")
        return aggregated

    def filter_extracted_fields_by_type(extracted_fields: Dict, entity_info: Dict) -> Dict:
        """
        Filter extracted fields based on field type:
        - Mandatory fields: Always include (even if empty)
        - Optional/Conditional fields: Only include if they have actual values
        
        Args:
            extracted_fields: Dictionary of extracted field data
            entity_info: Dictionary with mandatory_fields, optional_fields, conditional_fields
            
        Returns:
            Filtered dictionary of extracted fields
        """
        if not extracted_fields or not entity_info:
            return extracted_fields
            
        # Create sets of field names by type for efficient lookup
        mandatory_field_names = {field['entityName'].lower() for field in entity_info.get('mandatory_fields', [])}
        optional_field_names = {field['entityName'].lower() for field in entity_info.get('optional_fields', [])}
        conditional_field_names = {field['entityName'].lower() for field in entity_info.get('conditional_fields', [])}
        
        filtered_fields = {}
        
        for field_name, field_data in extracted_fields.items():
            field_name_lower = field_name.lower()
            field_value = field_data.get('value', '') if isinstance(field_data, dict) else str(field_data)
            
            # Check if field has actual content (not empty/null/whitespace)
            has_value = field_value and str(field_value).strip() and str(field_value).strip() not in ['', 'null', 'None', 'N/A', '-']
            
            # Always include mandatory fields (even if empty)
            if field_name_lower in mandatory_field_names:
                filtered_fields[field_name] = field_data
                
            # Only include optional/conditional fields if they have values
            elif (field_name_lower in optional_field_names or field_name_lower in conditional_field_names):
                if has_value:
                    filtered_fields[field_name] = field_data
                else:
                    logger.debug(f"🚫 Filtered out empty optional/conditional field: {field_name}")
                    
            # Include unmatched fields if they have values (fallback)
            else:
                if has_value:
                    filtered_fields[field_name] = field_data
                    
        logger.info(f"📋 Field filtering: {len(extracted_fields)} → {len(filtered_fields)} fields (removed {len(extracted_fields) - len(filtered_fields)} empty optional fields)")
        return filtered_fields

    def extract_entities_in_chunks(entity_info: Dict, ocr_text: str, model: str, page_number: int) -> List[Dict]:
        """
        Extract entities by dividing them into logical chunks for parallel processing.
        This ensures consistent results by processing specific entity groups in parallel.

        Args:
            entity_info: Dictionary with mandatory_fields, optional_fields, conditional_fields
            ocr_text: OCR text to extract from
            model: LLM model/engine to use
            page_number: Page number for logging

        Returns:
            List of extraction results from all chunks
        """
        logger.info(f"🧩 Starting chunk-based entity extraction for page {page_number}")

        # Load chunking configuration from YAML
        chunking_config = document_classifier.prompt_config.get('chunking', {})
        
        if not chunking_config.get('enabled', True):
            logger.warning("⚠️ Chunking is disabled in config - falling back to single extraction")
            # Could implement fallback to non-chunked extraction here
        
        # Get configuration values
        thresholds = chunking_config.get('entity_count_thresholds', {
            'small': 10,
            'medium': 20,
            'large': 30
        })
        chunk_counts = chunking_config.get('chunk_counts', {
            'small': 2,
            'medium': 3,
            'large': 4,
            'xlarge': 5
        })
        base_seed = chunking_config.get('base_seed', 12345)
        seed_increment = chunking_config.get('seed_increment_per_chunk', 1)
        min_entities_per_chunk = chunking_config.get('min_entities_per_chunk', 1)
        prioritize_mandatory = chunking_config.get('prioritize_mandatory_first', True)
        priority_order = chunking_config.get('priority_order', ['Mandatory', 'Optional', 'Conditional'])
        
        logger.info(f"📋 Chunking Configuration:")
        logger.info(f"   Thresholds: Small≤{thresholds['small']}, Medium≤{thresholds['medium']}, Large≤{thresholds['large']}")
        logger.info(f"   Chunk Counts: Small={chunk_counts['small']}, Medium={chunk_counts['medium']}, Large={chunk_counts['large']}, XLarge={chunk_counts['xlarge']}")
        logger.info(f"   Base Seed: {base_seed}, Increment: {seed_increment}")
        logger.info(f"   Min Entities/Chunk: {min_entities_per_chunk}")
        logger.info(f"   Prioritize Mandatory First: {prioritize_mandatory}")
        logger.info(f"   Priority Order: {priority_order}")

        # Calculate total entities
        all_entities = entity_info['mandatory_fields'] + entity_info['optional_fields'] + entity_info['conditional_fields']
        total_entities = len(all_entities)
        logger.info(f"📋 Total entities to extract: {total_entities} (Mandatory: {len(entity_info['mandatory_fields'])}, Optional: {len(entity_info['optional_fields'])}, Conditional: {len(entity_info['conditional_fields'])})")

        # Determine optimal number of chunks based on configuration
        if total_entities <= thresholds['small']:
            num_chunks = chunk_counts['small']
        elif total_entities <= thresholds['medium']:
            num_chunks = chunk_counts['medium']
        elif total_entities <= thresholds['large']:
            num_chunks = chunk_counts['large']
        else:
            num_chunks = chunk_counts['xlarge']
        
        logger.info(f"📦 Determined chunk count: {num_chunks} chunks for {total_entities} entities")

        # Always prioritize mandatory fields first, then optional, then conditional (if configured)
        chunk_size = max(min_entities_per_chunk, total_entities // num_chunks)
        entity_chunks = []
        
        current_chunk = []
        current_chunk_priority = []
        
        # Process entities in priority order (configurable)
        entity_groups = {
            'Mandatory': entity_info['mandatory_fields'],
            'Optional': entity_info['optional_fields'],
            'Conditional': entity_info['conditional_fields']
        }
        
        for priority in priority_order:
            for entity in entity_groups.get(priority, []):
                current_chunk.append(entity)
                current_chunk_priority.append(priority)
                if len(current_chunk) >= chunk_size and len(entity_chunks) < num_chunks - 1:
                    entity_chunks.append({
                        'entities': current_chunk.copy(),
                        'priorities': current_chunk_priority.copy(),
                        'chunk_id': len(entity_chunks) + 1
                    })
                    current_chunk = []
                    current_chunk_priority = []

        # Add remaining entities to the last chunk
        if current_chunk:
            entity_chunks.append({
                'entities': current_chunk,
                'priorities': current_chunk_priority,
                'chunk_id': len(entity_chunks) + 1
            })

        logger.info(f"📦 Created {len(entity_chunks)} entity chunks:")
        for i, chunk in enumerate(entity_chunks):
            mandatory_count = sum(1 for p in chunk['priorities'] if p == 'Mandatory')
            optional_count = sum(1 for p in chunk['priorities'] if p == 'Optional')
            conditional_count = sum(1 for p in chunk['priorities'] if p == 'Conditional')
            logger.info(f"   Chunk {i+1}: {len(chunk['entities'])} entities (M:{mandatory_count}, O:{optional_count}, C:{conditional_count})")

        def extract_chunk(chunk_info: Dict) -> Dict:
            """Extract entities for a specific chunk."""
            chunk_id = chunk_info['chunk_id']
            entities = chunk_info['entities']
            priorities = chunk_info['priorities']
            
            try:
                logger.info(f"   📤 Chunk {chunk_id}: Processing {len(entities)} entities")
                
                # Build field list for this chunk
                field_list = []
                field_definitions = {}
                
                for entity, priority in zip(entities, priorities):
                    field_name = entity['entityName']
                    field_desc = entity.get('description', '')
                    field_list.append(field_name)
                    
                    if field_desc:
                        field_definitions[field_name] = f"{field_name} ({priority}) - {field_desc}"
                    else:
                        field_definitions[field_name] = f"{field_name} ({priority})"

                # Build extraction prompt for this chunk
                chunk_prompt = document_classifier.build_extraction_prompt_for_entities(
                    field_list=field_list,
                    field_definitions=field_definitions,
                    ocr_text=ocr_text,
                    page_number=page_number,
                    chunk_id=chunk_id
                )

                logger.info(f"📋 ENTITY EXTRACTION REQUEST (Chunk {chunk_id}) TO AZURE OPENAI:")
                logger.info(f"  🌐 Endpoint: {openai.api_base}")
                logger.info(f"  🔑 API Key: {openai.api_key[:10]}...{openai.api_key[-4:] if openai.api_key and len(openai.api_key) > 14 else '***'}")
                logger.info(f"  📝 API Version: {openai.api_version}")
                logger.info(f"  🚀 Deployment/Engine: {model}")
                logger.info(f"  🔧 Temperature: 0")
                
                # Calculate seed from configuration
                chunk_seed = base_seed + (seed_increment * (chunk_id - 1))
                logger.info(f"  🎲 Seed: {chunk_seed} (base={base_seed}, increment={seed_increment}, chunk={chunk_id})")
                logger.info(f"  📊 Max Tokens: (default)")
                logger.info(f"  📄 Prompt Length: {len(chunk_prompt)} characters")
                logger.info(f"  📋 Chunk Fields: {len(field_list)} fields")
                logger.info(f"  📋 COMPLETE PROMPT (FULL - NO TRUNCATION):\n{chunk_prompt}")
                logger.info(f"📤 Calling Azure OpenAI for chunk {chunk_id} extraction...")

                # Make LLM call for this chunk
                response = openai.ChatCompletion.create(
                    engine=model,
                    messages=[{"role": "user", "content": chunk_prompt}],
                    temperature=0,
                    seed=chunk_seed,  # Use configured seed calculation
                    top_p=0.1,
                    frequency_penalty=0,
                    presence_penalty=0,
                    response_format={"type": "json_object"}
                )

                logger.info(f"✅ Azure OpenAI API call successful for chunk {chunk_id}")
                result = response["choices"][0]["message"]["content"].strip()
                logger.info(f"📊 ENTITY EXTRACTION RESPONSE (Chunk {chunk_id} - Raw):")
                logger.info(f"  📄 Content Length: {len(result)} characters")
                logger.info(f"  📋 Full Response (COMPLETE - NO TRUNCATION):\\n{result}")
                
                parsed_json = parse_json_from_llm_response(result)

                if parsed_json and 'extracted_fields' in parsed_json:
                    field_count = len(parsed_json.get('extracted_fields', {}))
                    logger.info(f"📊 ENTITY EXTRACTION RESPONSE (Chunk {chunk_id} - Parsed):")
                    logger.info(f"  ✅ Extracted fields: {field_count}/{len(entities)}")
                    logger.info(f"  📋 Extracted fields (COMPLETE):\\n{json.dumps(parsed_json.get('extracted_fields', {}), indent=2)}")
                    logger.info(f"   ✅ Chunk {chunk_id}: Extracted {field_count}/{len(entities)} fields")
                else:
                    logger.warning(f"   ⚠️  Chunk {chunk_id}: Failed to parse response")

                return parsed_json if parsed_json else {}

            except Exception as e:
                logger.error(f"   ❌ Chunk {chunk_id}: Error - {str(e)}")
                return {}

        # Execute parallel chunk extraction
        results = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(entity_chunks)) as executor:
            # Submit all chunk tasks
            future_to_chunk = {
                executor.submit(extract_chunk, chunk): chunk['chunk_id']
                for chunk in entity_chunks
            }

            # Collect results as they complete
            for future in concurrent.futures.as_completed(future_to_chunk):
                chunk_id = future_to_chunk[future]
                try:
                    result = future.result()
                    results.append(result)
                except Exception as e:
                    logger.error(f"   ❌ Chunk {chunk_id}: Exception - {str(e)}")
                    results.append({})

        successful_count = sum(1 for r in results if r and 'extracted_fields' in r)
        total_extracted = sum(len(r.get('extracted_fields', {})) for r in results if r)
        logger.info(f"🏁 Chunk extraction complete: {successful_count}/{len(entity_chunks)} chunks successful, {total_extracted} total fields extracted")

        return results

    def extract_entities_parallel(prompt: str, model: str, temperature: float, num_attempts: int = 3) -> List[Dict]:
        """
        Perform parallel entity extraction with multiple concurrent LLM calls.

        Args:
            prompt: The extraction prompt
            model: The model name/engine to use
            temperature: Temperature setting for LLM
            num_attempts: Number of parallel extraction attempts

        Returns:
            List of extraction results from all attempts
        """
        logger.info(f"🚀 Starting parallel extraction with {num_attempts} concurrent attempts")

        def single_extraction_call(attempt_num: int) -> Dict:
            """Single extraction call for parallel execution."""
            try:
                logger.info(f"   📤 Attempt {attempt_num + 1}/{num_attempts}: Sending request to LLM")
                response = openai.ChatCompletion.create(
                    engine=model,
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0,
                    seed=12345,  # ✅ Reproducibility
                    top_p=0.1,  # ✅ NOT 1.0 (reduces randomness)
                    frequency_penalty=0,
                    presence_penalty=0,
                    response_format={"type": "json_object"}
                )

                result = response["choices"][0]["message"]["content"].strip()
                parsed_json = parse_json_from_llm_response(result)

                if parsed_json and 'extracted_fields' in parsed_json:
                    field_count = len(parsed_json.get('extracted_fields', {}))
                    logger.info(f"   ✅ Attempt {attempt_num + 1}: Extracted {field_count} fields")
                else:
                    logger.warning(f"   ⚠️  Attempt {attempt_num + 1}: Failed to parse response")

                return parsed_json if parsed_json else {}

            except Exception as e:
                logger.error(f"   ❌ Attempt {attempt_num + 1}: Error - {str(e)}")
                return {}

        # Execute parallel extraction calls using ThreadPoolExecutor
        results = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=num_attempts) as executor:
            # Submit all extraction tasks
            future_to_attempt = {
                executor.submit(single_extraction_call, i): i
                for i in range(num_attempts)
            }

            # Collect results as they complete
            for future in concurrent.futures.as_completed(future_to_attempt):
                attempt_num = future_to_attempt[future]
                try:
                    result = future.result()
                    results.append(result)
                except Exception as e:
                    logger.error(f"   ❌ Attempt {attempt_num + 1}: Exception - {str(e)}")
                    results.append({})

        successful_count = sum(1 for r in results if r and 'extracted_fields' in r)
        logger.info(f"🏁 Parallel extraction complete: {successful_count}/{num_attempts} successful attempts")

        return results

    def process_page_with_llm_analysis(page_number, page_ocr_data, userQuery, annotations, productName, functionName, documentType=None):
        global prompt_config  # Declare at function start to avoid SyntaxError

        logger.info(f"=== Starting process_page_with_llm_analysis for page {page_number} ===")
        logger.info(f"UserQuery: {userQuery}, Product: {productName}, Function: {functionName}, DocumentType: {documentType}")

        # Load prompt configuration at the beginning
        if not prompt_config:
            prompt_config = load_prompt_config()
            if prompt_config:
                logger.info(f"SUCCESS:Loaded prompt configuration from YAML")

        page_text = " ".join([entry["text"] for entry in page_ocr_data])
        token_count = calculate_text_token_count(page_text)
        logger.info(f"Page {page_number} token count: {token_count}")

        # if token_count > 16000:
        #     logging.warning(f"Page {page_number} exceeds token limit. Truncating.")
        #     page_text = page_text[:20000]

        ocr_text = format_ocr_data_for_llm_prompt(page_ocr_data)

        # STEP 1: Document Classification (EXISTING LOGIC)
        logger.info(f"Calling document_classifier.classify_document for page {page_number}")
        logger.info(f"Current OpenAI config before classification - API Base: {openai.api_base}, Key exists: {bool(openai.api_key)}")

        classification_result = document_classifier.classify_document(page_text)

        logger.info(f"Classification result for page {page_number}: {classification_result}")
        document_type = classification_result.get("document_type", "unknown")

        # Override with user query if provided
        if userQuery and userQuery.lower() in ["letter_of_credit", "invoice", "export_collection", "bank_guarantee"]:
            document_type = userQuery.lower()

        # Use provided documentType if available (this takes highest priority)
        if documentType:
            document_type = documentType
            logger.info(f" Using explicitly provided document type: {documentType}")

        # STEP 2: Map classified document type to UN/CEFACT code
        def map_document_type_to_uncefact_code(doc_type):
            """Map classified document type to UN/CEFACT document code"""
            mapping = {
                "letter_of_credit": "LC",
                "letter of credit": "LC",
                "lc": "LC",
                "commercial_invoice": "INV",
                "commercial invoice": "INV",
                "invoice": "INV",
                "bill_of_lading": "BoL",
                "bill of lading": "BoL",
                "bol": "BoL",
                "certificate_of_origin": "CoO",
                "certificate of origin": "CoO",
                "coo": "CoO",
                "packing_list": "PL",
                "packing list": "PL",
                "air_waybill": "AW",
                "air waybill": "AW",
                "sea_waybill": "SW",
                "sea waybill": "SW",
                "cargo_insurance": "CID",
                "insurance_certificate": "CID",
                "bank_guarantee": "LC",  # Bank guarantees use similar structure
                "customs_declaration": "CD",
                "phytosanitary_certificate": "ePhyto",
                "warehouse_receipt": "WR",
                "dangerous_goods_declaration": "DGD",
                "bill_of_exchange": "BoE",
                "promissory_note": "PN",
                "payment_confirmation": "PC"
            }
            return mapping.get(doc_type.lower(), None)

        # STEP 3: Try to get UN/CEFACT code from classification
        uncefact_code = map_document_type_to_uncefact_code(document_type)

        if uncefact_code:
            logger.info(f"Mapped '{document_type}' → UN/CEFACT code: '{uncefact_code}'")
        else:
            logger.info(f"No UN/CEFACT mapping found for document type: '{document_type}'")

        # STEP 4: Get fields from entity_mappings (document_entity_maintenance.json)
        doc_type_normalized = classification_result.get("document_type", "").replace(" ", "_")
        if not doc_type_normalized:
            doc_type_normalized = document_type.replace(" ", "_")

        logger.info(f" Getting entity fields for: {doc_type_normalized}")
        entity_info = document_classifier.get_enhanced_entity_fields(doc_type_normalized)

        field_list = []
        field_definitions = {}

        # Build field list from entity mappings with enhanced descriptions
        for field in entity_info['mandatory_fields']:
            field_name = field['entityName']
            field_desc = field.get('description', '')
            field_list.append(field_name)
            if field_desc:
                field_definitions[field_name] = f"{field_name} (Mandatory) - {field_desc}"
            else:
                field_definitions[field_name] = f"{field_name} (Mandatory)"

        for field in entity_info['optional_fields']:
            field_name = field['entityName']
            field_desc = field.get('description', '')
            field_list.append(field_name)
            if field_desc:
                field_definitions[field_name] = f"{field_name} (Optional) - {field_desc}"
            else:
                field_definitions[field_name] = f"{field_name} (Optional)"

        for field in entity_info['conditional_fields']:
            field_name = field['entityName']
            field_desc = field.get('description', '')
            field_list.append(field_name)
            if field_desc:
                field_definitions[field_name] = f"{field_name} (Conditional) - {field_desc}"
            else:
                field_definitions[field_name] = f"{field_name} (Conditional)"

        logger.info(f"SUCCESS:Using entity_mappings with descriptions: {len(field_list)} fields ({len(entity_info['mandatory_fields'])} mandatory, {len(entity_info['optional_fields'])} optional, {len(entity_info['conditional_fields'])} conditional)")

        # Log sample field with description for verification
        if field_list:
            sample_field_name = field_list[0]
            sample_field_def = field_definitions.get(sample_field_name, '')
            logger.info(f"ANALYTICS: Sample field with description: {sample_field_def}")

        # Store for later use
        trade_doc_fields = {
            'mandatory': entity_info['mandatory_fields'],
            'optional': entity_info['optional_fields'],
            'conditional': entity_info['conditional_fields']
        }

        try:
            # Use DocumentClassifier to build extraction prompt from config and entity_mappings
            logger.info(f"")
            logger.info(f"{'='*100}")
            logger.info(f"🔍 STEP 1: PRIMARY ENTITY DEFINITION (from document_entity_maintenance.json)")
            logger.info(f"{'='*100}")
            logger.info(f"📄 Document Type: {document_type}")
            logger.info(f"📝 Page Number: {page_number}")
            logger.info(f"🏗️ Building extraction prompt using DocumentClassifier...")
            
            prompt = document_classifier.build_extraction_prompt(
                document_type=document_type,
                ocr_text=page_text,
                page_number=page_number
            )
            
            logger.info(f"✅ STEP 1 COMPLETE: Extraction prompt built successfully from primary entity definitions")
            logger.info(f"📊 Primary Prompt Length: {len(prompt)} characters")
            logger.info(f"📋 PRIMARY EXTRACTION PROMPT (COMPLETE - NO TRUNCATION):\n{prompt}")
            logger.info(f"{'='*100}")
            logger.info(f"")

            # === ENHANCEMENT: Add field mapping examples from document_entities ===
            original_prompt_length = len(prompt)
            field_mapping_example = load_document_field_mappings(document_type)
            
            if field_mapping_example:
                prompt += f"\n\n{field_mapping_example}"
                enhancement_length = len(field_mapping_example)
                logger.info(f"")
                logger.info(f"{'='*100}")
                logger.info(f"🔗 PROMPT ENHANCEMENT: Combining Step 1 + Step 2")
                logger.info(f"{'='*100}")
                logger.info(f"📊 Original Prompt (Step 1): {original_prompt_length} characters")
                logger.info(f"➕ Enhancement Text (Step 2): {enhancement_length} characters")
                logger.info(f"📋 Combined Prompt Total: {len(prompt)} characters")
                logger.info(f"✅ Prompt enhanced with field mapping examples for {document_type}")
                logger.info(f"📋 FINAL COMBINED PROMPT (COMPLETE - NO TRUNCATION):\n{prompt}")
                logger.info(f"{'='*100}")
                logger.info(f"")
            else:
                logger.info(f"")
                logger.info(f"{'='*100}")
                logger.info(f"ℹ️ NO ENHANCEMENT: Using only Step 1 (primary entity definitions)")
                logger.info(f"{'='*100}")
                logger.info(f"📊 Final Prompt Length: {len(prompt)} characters (no enhancement added)")
                logger.info(f"📋 FINAL PROMPT (COMPLETE - NO TRUNCATION):\n{prompt}")
                logger.info(f"{'='*100}")
                logger.info(f"")

            # Load prompt configuration for model settings (already declared global at function start)
            if not prompt_config:
                prompt_config = load_prompt_config()

            # Fallback if build_extraction_prompt fails
            if not prompt:
                logger.error("ERROR: Failed to build extraction prompt from DocumentClassifier, using basic fallback")
                prompt = f"Extract fields from this {document_type} document:\n\n{page_text}"

            # Get model settings from config (with fallback to defaults)
            temperature = 0.0
            model = deployment_name
            if prompt_config:
                temperature = prompt_config.get('extraction', {}).get('temperature', 0.0)
                model = prompt_config.get('extraction', {}).get('model', deployment_name)

            logger.info(f"PARAMETERS: Using extraction config - Model: {model}, Temperature: {temperature}")

            # Check if parallel extraction is enabled
            extraction_config = prompt_config.get('extraction', {}) if prompt_config else {}
            enable_parallel = extraction_config.get('enable_parallel_extraction', False)
            parallel_attempts = extraction_config.get('parallel_extraction_attempts', 3)
            aggregation_strategy = extraction_config.get('aggregation_strategy', 'union')
            confidence_threshold = extraction_config.get('confidence_threshold', 70)

            if enable_parallel and parallel_attempts > 1:
                # ======= NEW: CHUNK-BASED EXTRACTION MODE =======
                logger.info(f"🧩 Chunk-based extraction ENABLED: Processing entities in logical chunks")

                # Use new chunk-based extraction instead of redundant parallel calls
                extraction_results = extract_entities_in_chunks(
                    entity_info=entity_info,
                    ocr_text=page_text,
                    model=model if model else deployment_name,
                    page_number=page_number
                )

                # Merge results from all chunks
                merged_results = {"extracted_fields": {}}
                total_fields_extracted = 0
                
                for result in extraction_results:
                    if result and 'extracted_fields' in result:
                        merged_results["extracted_fields"].update(result["extracted_fields"])
                        total_fields_extracted += len(result["extracted_fields"])

                # ======= FILTER FIELDS BY TYPE: Keep mandatory always, optional/conditional only if they have values =======
                filtered_fields = filter_extracted_fields_by_type(
                    extracted_fields=merged_results["extracted_fields"],
                    entity_info=entity_info
                )
                merged_results["extracted_fields"] = filtered_fields

                # Set merged result as final parsed_json
                parsed_json = merged_results
                parsed_json["page_number"] = page_number
                parsed_json["confidence_score"] = 85  # Default confidence for chunk-based extraction
                
                # Add statistics (updated after filtering)
                parsed_json["mandatory_fields_found"] = sum(1 for field_name in parsed_json["extracted_fields"].keys() 
                                                         if any(field_name.lower() == mf['entityName'].lower() 
                                                               for mf in entity_info['mandatory_fields']))
                parsed_json["total_mandatory_fields"] = len(entity_info['mandatory_fields'])
                parsed_json["total_fields_extracted"] = len(filtered_fields)  # Updated count after filtering
                parsed_json["extraction_method"] = "chunk_based"

                logger.info(f"✅ Chunk-based extraction successful: {len(filtered_fields)} filtered fields from {len(extraction_results)} chunks (was {total_fields_extracted} before filtering)")

                if not parsed_json or 'extracted_fields' not in parsed_json:
                    logger.error("❌ Chunk-based extraction failed, no valid results")
                    return {"page_number": page_number, "error": "Chunk-based extraction failed"}

            else:
                # ======= SINGLE EXTRACTION MODE (Original) =======
                logger.info(f"📤 Single extraction mode (parallel disabled or attempts=1)")

                # Send prompt to LLM (note: build_extraction_prompt already includes system prompt)
                response = openai.ChatCompletion.create(
                    engine=model if model else deployment_name,
                    messages=[
                        {"role": "user", "content": prompt}
                    ],
                    temperature=0,
                    seed=12345,  # ✅ Reproducibility
                    top_p=0.1,  # ✅ NOT 1.0 (reduces randomness)
                    frequency_penalty=0,
                    presence_penalty=0,
                    response_format={"type": "json_object"}
                )

                result = response["choices"][0]["message"]["content"].strip()
                parsed_json = parse_json_from_llm_response(result)
                if not parsed_json:
                    return {"page_number": page_number, "error": "Invalid LLM response format"}

                # ======= FILTER FIELDS BY TYPE (Single Extraction) =======
                if parsed_json.get('extracted_fields') and entity_info:
                    filtered_fields = filter_extracted_fields_by_type(
                        extracted_fields=parsed_json["extracted_fields"],
                        entity_info=entity_info
                    )
                    parsed_json["extracted_fields"] = filtered_fields
                    logger.info(f"📋 Single extraction: Applied field filtering (mandatory always shown, optional/conditional only if populated)")

            # Ensure compliance results are included for all document types
            # No need to remove compliance results anymore

            # Enhanced logging for trade document field extraction
            if trade_doc_fields and parsed_json.get("extracted_fields"):
                extracted_field_names = list(parsed_json["extracted_fields"].keys())
                logger.info(f"ANALYTICS: Page {page_number} - Extracted {len(extracted_field_names)} fields from document")

                # Log mandatory fields that were found
                mandatory_found = [f['entityName'] for f in trade_doc_fields['mandatory']
                                 if any(f['entityName'] in field or f['entityName'].lower().replace(' ', '_') in field.lower()
                                       for field in extracted_field_names)]
                if mandatory_found:
                    logger.info(f"SUCCESS:Mandatory fields found: {', '.join(mandatory_found[:5])}{'...' if len(mandatory_found) > 5 else ''}")

                # Log optional fields that were found
                optional_found = [f['entityName'] for f in trade_doc_fields['optional']
                                if any(f['entityName'] in field or f['entityName'].lower().replace(' ', '_') in field.lower()
                                      for field in extracted_field_names)]
                if optional_found:
                    logger.info(f"Optional fields found: {', '.join(optional_found[:5])}{'...' if len(optional_found) > 5 else ''}")

                # Log which mandatory fields are missing
                mandatory_missing = [f['entityName'] for f in trade_doc_fields['mandatory']
                                   if not any(f['entityName'] in field or f['entityName'].lower().replace(' ', '_') in field.lower()
                                            for field in extracted_field_names)]
                if mandatory_missing:
                    logger.warning(f"WARNINGS:  Missing mandatory fields: {', '.join(mandatory_missing[:5])}{'...' if len(mandatory_missing) > 5 else ''}")

            logging.info(f"Comprehensive analysis result for page {page_number}: {parsed_json}")
            return parsed_json

        except Exception as e:
            logging.error(f"Error analyzing page {page_number}: {e}")
            return {"page_number": page_number, "error": "Failed to analyze the page."}

